export const EMBEDDED_ASSETS = {
  "index.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, viewport-fit=cover\">\n  <meta name=\"theme-color\" content=\"#0a0a0c\">\n  <meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n  <meta name=\"apple-mobile-web-app-status-bar-style\" content=\"black-translucent\">\n  <title>uDrop — Instant Cross-Platform P2P</title>\n  <link rel=\"icon\" type=\"image/svg+xml\" href=\"assets/icon-brand.svg\">\n  <link rel=\"manifest\" href=\"manifest.json\">\n  <link rel=\"stylesheet\" href=\"style.css\">\n</head>\n<body>\n  <!-- Liquid Glass Optical Pairing Overlay Modal -->\n  <div id=\"qrGlassModal\" class=\"glass-modal-overlay hidden\" aria-hidden=\"true\">\n    <div class=\"glass-modal-backdrop\" id=\"qrModalBackdrop\"></div>\n    <div class=\"glass-modal-container\">\n      <div class=\"glass-modal-panel\" id=\"glassModalPanel\">\n        <!-- Top Control Bar -->\n        <div class=\"glass-modal-header\">\n          <div class=\"glass-theme-picker\">\n            <button class=\"glass-theme-btn active\" data-theme=\"obsidian\">Obsidian</button>\n            <button class=\"glass-theme-btn\" data-theme=\"titanium\">Titanium</button>\n            <button class=\"glass-theme-btn\" data-theme=\"paper\">Inverted White</button>\n          </div>\n          <button id=\"closeQrModalBtn\" class=\"glass-close-btn\" title=\"Close (Esc)\">\n            <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"></line><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"></line></svg>\n          </button>\n        </div>\n\n        <!-- Sleek Vector Card Viewport -->\n        <div class=\"glass-card-viewport\">\n          <div class=\"glass-qr-wrapper\" id=\"glassQrWrapper\">\n            <canvas id=\"glassQrCanvas\" class=\"glass-qr-canvas\" aria-label=\"uDrop Optical Pairing Card\"></canvas>\n          </div>\n        </div>\n\n        <!-- Footer Caption -->\n        <div class=\"glass-modal-footer\">\n          <span class=\"glass-hint\">Scan with iPhone or Android camera to beam files</span>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"app-container\">\n    <header class=\"app-header\">\n      <div class=\"brand\">\n        <img src=\"assets/icon-brand.svg\" alt=\"uDrop Icon\" class=\"brand-icon\">\n        <div class=\"brand-text\">\n          <span class=\"logo-badge\">uDrop</span>\n          <span class=\"brand-sub\">UXIOM MESH</span>\n        </div>\n      </div>\n      <div class=\"header-right\">\n        <button id=\"openQrModalBtn\" class=\"btn-qr-pill\" title=\"Show Optical Pairing Liquid Glass Card\">\n          <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"3\" width=\"7\" height=\"7\" rx=\"1.5\"></rect><rect x=\"14\" y=\"3\" width=\"7\" height=\"7\" rx=\"1.5\"></rect><rect x=\"14\" y=\"14\" width=\"7\" height=\"7\" rx=\"1.5\"></rect><rect x=\"3\" y=\"14\" width=\"7\" height=\"7\" rx=\"1.5\"></rect></svg>\n          <span class=\"btn-text\">Pair QR</span>\n        </button>\n        <div class=\"connection-status\" id=\"connectionStatusPill\">\n          <span class=\"status-dot\"></span>\n          <span id=\"hostName\">Connecting to Host...</span>\n        </div>\n      </div>\n    </header>\n\n    <main class=\"main-content\">\n      <!-- Section: UXIOM 5-Node Mesh Ring Topology -->\n      <section class=\"card mesh-card\">\n        <div class=\"card-header\">\n          <div class=\"mesh-title\">\n            <span class=\"pulse-indicator\"></span>\n            <h2>UXIOM Ring Topology</h2>\n          </div>\n          <span id=\"mySlotBadge\" class=\"my-slot-badge\">Assigned: [ - ]</span>\n        </div>\n\n        <div class=\"mesh-ring-container\">\n          <div id=\"meshRing\" class=\"mesh-ring\">\n            <!-- Dynamically populated: [ U ], [ X ], [ I ], [ O ], [ M ], and [ SWARM ] -->\n          </div>\n        </div>\n\n        <div class=\"mesh-target-bar\">\n          <span class=\"target-label\">Target Recipient:</span>\n          <span id=\"targetNodeText\" class=\"target-node-text\">[ U ] Master Host</span>\n        </div>\n      </section>\n\n      <!-- Section: Send Files -->\n      <section class=\"card upload-card\">\n        <div class=\"card-header\">\n          <h2>Stream to Target</h2>\n          <span class=\"badge\">Zero-Router 4K</span>\n        </div>\n\n        <div id=\"dropzone\" class=\"dropzone\">\n          <input type=\"file\" id=\"fileInput\" multiple class=\"file-input\" />\n          <input type=\"file\" id=\"mediaInput\" multiple accept=\"video/*,image/*\" class=\"file-input-media\" style=\"display: none;\" />\n          <div class=\"dropzone-content\">\n            <div id=\"dropzoneIconWrapper\" class=\"dropzone-icon-box\">\n              <svg width=\"28\" height=\"28\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                <path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"></path>\n                <polyline points=\"17 8 12 3 7 8\"></polyline>\n                <line x1=\"12\" y1=\"3\" x2=\"12\" y2=\"15\"></line>\n              </svg>\n            </div>\n            <div id=\"mascotFace\" class=\"mascot-face\" style=\"display: none;\"></div>\n            <p id=\"dropzoneActionText\" class=\"dropzone-text\">Tap or Drag Files to Stream</p>\n            <span id=\"dropzoneHintText\" class=\"dropzone-hint\">Photos, 4K ProRes Videos, Large Archives</span>\n            <div class=\"dropzone-quick-actions\" id=\"dropzoneQuickActions\">\n              <button type=\"button\" class=\"btn-picker-pill\" id=\"pickMediaBtn\">\n                <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\"><rect x=\"2\" y=\"2\" width=\"20\" height=\"20\" rx=\"5\" ry=\"5\"></rect><circle cx=\"8.5\" cy=\"8.5\" r=\"1.5\"></circle><polyline points=\"21 15 16 10 5 21\"></polyline></svg>\n                <span>Select Videos / Photos</span>\n              </button>\n              <button type=\"button\" class=\"btn-picker-pill outline\" id=\"pickFilesBtn\">\n                <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"></path><polyline points=\"14 2 14 8 20 8\"></polyline></svg>\n                <span>All Files</span>\n              </button>\n            </div>\n          </div>\n        </div>\n\n        <!-- Transfer Progress Area -->\n        <div id=\"transferContainer\" class=\"transfer-container hidden\">\n          <!-- Batch Summary Bar (Visible for multi-file batches) -->\n          <div id=\"batchSummaryBar\" class=\"batch-summary-bar hidden\">\n            <div class=\"batch-summary-info\">\n              <div class=\"batch-title-row\">\n                <span class=\"batch-title\">Batch Transfer Queue</span>\n                <span id=\"batchCountBadge\" class=\"batch-count-badge\">0 / 0</span>\n              </div>\n              <span id=\"batchProgressStats\" class=\"batch-progress-stats\">0 MB / 0 MB (0%)</span>\n            </div>\n            <div class=\"progress-bar-bg batch-progress-bg\">\n              <div id=\"batchProgressBar\" class=\"progress-bar-fill batch-fill\" style=\"width: 0%\"></div>\n            </div>\n          </div>\n\n          <!-- Active File Progress Info -->\n          <div class=\"transfer-info\">\n            <div class=\"transfer-title-group\">\n              <span id=\"transferFileName\" class=\"transfer-file-name\">filename.mp4</span>\n              <span id=\"transferStats\" class=\"transfer-stats\">0 MB / 0 MB</span>\n            </div>\n            <div class=\"transfer-metrics\">\n              <span id=\"transferSpeed\" class=\"transfer-speed\">0.0 MB/s</span>\n              <span id=\"transferEta\" class=\"transfer-eta\">--:--</span>\n            </div>\n          </div>\n\n          <div class=\"progress-bar-bg\">\n            <div id=\"progressBar\" class=\"progress-bar-fill\" style=\"width: 0%\"></div>\n          </div>\n\n          <div class=\"transfer-footer\">\n            <div class=\"transfer-footer-left\">\n              <span id=\"transferChunks\" class=\"chunk-badge\">Chunk 0 / 0</span>\n              <span id=\"transferStatus\" class=\"transfer-status-text\">Uploading...</span>\n            </div>\n            <button id=\"cancelTransferBtn\" class=\"btn-cancel-transfer\" type=\"button\" title=\"Cancel upload\">\n              <svg width=\"11\" height=\"11\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"></line><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"></line></svg>\n              <span>Cancel</span>\n            </button>\n          </div>\n\n          <!-- Detailed Multi-Item Queue List -->\n          <div id=\"queueListWrapper\" class=\"queue-list-wrapper hidden\">\n            <div class=\"queue-list-header\">\n              <span class=\"queue-list-title\">Queue Items</span>\n              <button id=\"retryFailedBtn\" class=\"btn-retry-failed hidden\" type=\"button\">\n                <svg width=\"11\" height=\"11\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><polyline points=\"23 4 23 10 17 10\"></polyline><path d=\"M20.49 15a9 9 0 1 1-2.12-9.36L23 10\"></path></svg>\n                <span id=\"retryFailedBtnText\">Retry Failed</span>\n              </button>\n            </div>\n            <div id=\"queueItemsList\" class=\"queue-items-list\">\n              <!-- Dynamically populated -->\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- Section: Incoming Mesh Transfer Notification -->\n      <div id=\"incomingTransferCard\" class=\"card incoming-card hidden\">\n        <div class=\"card-header\">\n          <div class=\"incoming-header-left\">\n            <span class=\"incoming-badge\">Incoming Mesh Transfer</span>\n            <span id=\"incomingFromText\" class=\"incoming-from\">From Node [O]</span>\n          </div>\n          <button id=\"dismissIncomingBtn\" class=\"btn-dismiss-incoming\" title=\"Dismiss\">\n            <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"></line><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"></line></svg>\n          </button>\n        </div>\n        <div class=\"incoming-body\">\n          <div class=\"incoming-info\">\n            <h3 id=\"incomingFileName\">VID_4K.mp4</h3>\n            <span id=\"incomingFileSize\">0 MB</span>\n          </div>\n          <a id=\"incomingDownloadBtn\" href=\"#\" class=\"btn-incoming-download\" download>Download File</a>\n        </div>\n      </div>\n\n      <!-- Section: Download from Host -->\n      <section class=\"card download-card\">\n        <div class=\"card-header\">\n          <h2>Files from Host</h2>\n          <button id=\"refreshFilesBtn\" class=\"btn-icon\" title=\"Refresh\">↻</button>\n        </div>\n        <div id=\"hostFilesList\" class=\"host-files-list\">\n          <p class=\"empty-state\">No files currently shared by the host.</p>\n        </div>\n      </section>\n    </main>\n\n    <footer class=\"app-footer\">\n      <span>100% Offline P2P • UXIOM Ring Mesh • Zero Cloud Storage</span>\n    </footer>\n  </div>\n\n  <!-- Background Media Anchor to Keep Mobile Screen Awake and Prevent Throttling on HTTP -->\n  <video id=\"wakeLockVideo\" playsinline muted loop style=\"display:none; width:1px; height:1px; position:fixed; opacity:0; pointer-events:none;\"></video>\n\n  <script src=\"qr-kinetic.js\"></script>\n  <script src=\"app.js\"></script>\n</body>\n</html>\n",
  "style.css": ":root {\n  /* Strict Monochromatic Zinc System (mono skill & tokens spec) */\n  --bg-primary: #09090B;              /* zinc950 */\n  --bg-card: rgba(24, 24, 27, 0.78);   /* zinc900 translucent glass */\n  --bg-surface: #18181B;             /* zinc900 */\n  --bg-surface-elevated: #27272A;    /* zinc800 */\n  --border-color: rgba(255, 255, 255, 0.08); /* crisp 1px border */\n  --border-highlight: rgba(255, 255, 255, 0.18);\n  --border-focus: rgba(255, 255, 255, 0.35);\n\n  /* Monochromatic Typography */\n  --text-main: #FAFAFA;              /* zinc50 */\n  --text-muted: #A1A1AA;             /* zinc400 */\n  --text-dim: #71717A;               /* zinc500 */\n\n  /* 5% Semantic Status Tokens */\n  --status-green: #22C55E;\n  --status-green-glow: rgba(34, 197, 94, 0.4);\n\n  /* Monochromatic Interactive Tokens */\n  --btn-primary-bg: #FAFAFA;\n  --btn-primary-fg: #09090B;\n  --btn-primary-hover: #E4E4E7;\n  --btn-secondary-bg: rgba(255, 255, 255, 0.06);\n  --btn-secondary-border: rgba(255, 255, 255, 0.12);\n  --btn-secondary-fg: #FAFAFA;\n\n  --font-family: -apple-system, BlinkMacSystemFont, \"SF Pro Text\", \"SF Pro Display\", \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\n  --font-mono: ui-monospace, SFMono-Regular, \"SF Mono\", Menlo, Consolas, monospace;\n\n  /* Backward Compatibility Aliases */\n  --apple-blue: #FAFAFA;\n  --apple-blue-fill: #FAFAFA;\n  --apple-green: var(--status-green);\n  --apple-amber: var(--text-muted);\n  --apple-indigo: #FAFAFA;\n  --accent-cyan: #FAFAFA;\n  --accent-purple: #FAFAFA;\n}\n\n* {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n  -webkit-tap-highlight-color: transparent;\n}\n\nbody {\n  font-family: var(--font-family);\n  background-color: var(--bg-primary);\n  color: var(--text-main);\n  min-height: 100vh;\n  min-height: -webkit-fill-available;\n  display: flex;\n  justify-content: center;\n  align-items: flex-start;\n  padding: max(16px, env(safe-area-inset-top, 16px))\n           max(14px, env(safe-area-inset-right, 14px))\n           max(24px, env(safe-area-inset-bottom, 24px))\n           max(14px, env(safe-area-inset-left, 14px));\n  background-image: radial-gradient(circle at 50% 0%, rgba(255, 255, 255, 0.03) 0%, transparent 60%);\n  -webkit-font-smoothing: antialiased;\n  -moz-osx-font-smoothing: grayscale;\n}\n\n.app-container {\n  width: 100%;\n  max-width: 580px;\n  display: flex;\n  flex-direction: column;\n  gap: 16px;\n  position: relative;\n  z-index: 1;\n}\n\n/* =========================================================\n   Header & Navigation\n   ========================================================= */\n.app-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 12px 18px;\n  background: var(--bg-card);\n  backdrop-filter: blur(28px) saturate(180%);\n  -webkit-backdrop-filter: blur(28px) saturate(180%);\n  border: 1px solid var(--border-color);\n  border-radius: 18px;\n  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.4);\n}\n\n.brand {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n}\n\n.brand-icon {\n  width: 32px;\n  height: 32px;\n  border-radius: 9px;\n  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.4);\n}\n\n.brand-text {\n  display: flex;\n  flex-direction: column;\n}\n\n.logo-badge {\n  font-size: 18px;\n  font-weight: 800;\n  letter-spacing: -0.4px;\n  color: var(--text-main);\n}\n\n.brand-sub {\n  font-size: 9.5px;\n  color: var(--text-dim);\n  text-transform: uppercase;\n  letter-spacing: 0.8px;\n  font-weight: 600;\n}\n\n.header-right {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  flex-shrink: 1;\n  min-width: 0;\n}\n\n.btn-qr-pill {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  background: rgba(255, 255, 255, 0.06);\n  border: 1px solid rgba(255, 255, 255, 0.12);\n  color: var(--text-main);\n  text-decoration: none;\n  font-size: 11.5px;\n  font-weight: 700;\n  padding: 6px 12px;\n  border-radius: 9999px;\n  cursor: pointer;\n  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);\n  flex-shrink: 0;\n}\n\n.btn-qr-pill:hover {\n  background: rgba(255, 255, 255, 0.12);\n  border-color: rgba(255, 255, 255, 0.22);\n  transform: translateY(-1px);\n}\n\n.btn-qr-pill svg {\n  stroke: var(--text-main);\n  flex-shrink: 0;\n}\n\n.connection-status {\n  display: inline-flex;\n  align-items: center;\n  gap: 7px;\n  font-size: 11.5px;\n  color: var(--text-muted);\n  background: rgba(255, 255, 255, 0.04);\n  padding: 6px 11px;\n  border-radius: 9999px;\n  border: 1px solid var(--border-color);\n  max-width: 180px;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  flex-shrink: 1;\n}\n\n.connection-status #hostName {\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  display: inline-block;\n  max-width: 130px;\n  font-weight: 500;\n}\n\n.status-dot {\n  width: 7px;\n  height: 7px;\n  border-radius: 50%;\n  background-color: var(--status-green);\n  box-shadow: 0 0 6px var(--status-green-glow);\n  animation: pulse 2.4s infinite ease-in-out;\n  flex-shrink: 0;\n}\n\n@keyframes pulse {\n  0%, 100% { opacity: 0.9; transform: scale(1); }\n  50% { opacity: 0.45; transform: scale(0.92); }\n}\n\n/* =========================================================\n   Universal Card Components\n   ========================================================= */\n.card {\n  background: var(--bg-card);\n  backdrop-filter: blur(28px) saturate(180%);\n  -webkit-backdrop-filter: blur(28px) saturate(180%);\n  border: 1px solid var(--border-color);\n  border-radius: 20px;\n  padding: 22px;\n  display: flex;\n  flex-direction: column;\n  gap: 16px;\n  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.45);\n}\n\n.card-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n}\n\n.card-header h2 {\n  font-size: 16px;\n  font-weight: 700;\n  letter-spacing: -0.3px;\n  color: var(--text-main);\n}\n\n.badge {\n  font-family: var(--font-mono);\n  font-size: 10.5px;\n  font-weight: 700;\n  background: rgba(255, 255, 255, 0.06);\n  color: var(--text-muted);\n  padding: 4px 9px;\n  border-radius: 6px;\n  border: 1px solid var(--border-color);\n}\n\n/* =========================================================\n   UXIOM 5-Node Mesh Ring Topology\n   ========================================================= */\n.mesh-card {\n  border-color: var(--border-color);\n  background: var(--bg-card);\n}\n\n.mesh-title {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n\n.pulse-indicator {\n  width: 6px;\n  height: 6px;\n  border-radius: 50%;\n  background: var(--status-green);\n  box-shadow: 0 0 6px var(--status-green-glow);\n}\n\n.my-slot-badge {\n  font-family: var(--font-mono);\n  font-size: 10.5px;\n  font-weight: 700;\n  background: rgba(255, 255, 255, 0.06);\n  color: var(--text-main);\n  border: 1px solid rgba(255, 255, 255, 0.12);\n  padding: 4px 9px;\n  border-radius: 8px;\n}\n\n.mesh-ring-container {\n  display: block;\n  width: 100%;\n  padding: 2px 0;\n}\n\n.mesh-ring {\n  display: grid;\n  grid-template-columns: repeat(6, 1fr);\n  gap: 8px;\n  width: 100%;\n}\n\n.ring-node {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  width: 100%;\n  min-height: 72px;\n  background: rgba(255, 255, 255, 0.02);\n  border: 1px dashed rgba(255, 255, 255, 0.10);\n  border-radius: 14px;\n  padding: 8px 4px;\n  cursor: pointer;\n  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);\n  position: relative;\n  box-sizing: border-box;\n}\n\n.ring-node:hover {\n  background: rgba(255, 255, 255, 0.05);\n  border-color: rgba(255, 255, 255, 0.22);\n}\n\n.ring-node-letter {\n  font-family: var(--font-mono);\n  font-size: 14.5px;\n  font-weight: 800;\n  letter-spacing: -0.2px;\n  color: var(--text-dim);\n  transition: color 0.2s;\n  white-space: nowrap !important;\n  display: inline-block;\n  line-height: 1.2;\n}\n\n.ring-node-letter-all {\n  font-size: 12px !important;\n  letter-spacing: -0.4px;\n}\n\n.ring-node-device {\n  font-size: 9.5px;\n  color: var(--text-dim);\n  text-align: center;\n  margin-top: 4px;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  width: 100%;\n  max-width: 100%;\n  box-sizing: border-box;\n  padding: 0 4px;\n}\n\n.ring-node-active {\n  border: 1px solid rgba(255, 255, 255, 0.16);\n  background: rgba(255, 255, 255, 0.04);\n}\n\n.ring-node-active .ring-node-letter {\n  color: var(--text-main);\n  font-weight: 800;\n}\n\n.ring-node-active .ring-node-device {\n  color: var(--text-muted);\n  font-weight: 500;\n}\n\n.ring-node-self {\n  border: 1.5px solid #FAFAFA;\n  background: rgba(255, 255, 255, 0.08);\n}\n\n.ring-node-self .ring-node-letter {\n  color: #FAFAFA;\n}\n\n.ring-node-selected {\n  border: 1.5px solid #FAFAFA;\n  background: rgba(255, 255, 255, 0.14);\n  transform: translateY(-2px);\n  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.5);\n}\n\n.ring-node-selected .ring-node-letter {\n  color: #FAFAFA;\n}\n\n.self-tag {\n  position: absolute;\n  top: -6px;\n  right: -4px;\n  font-size: 8.5px;\n  font-weight: 900;\n  background: #FAFAFA;\n  color: #09090B;\n  padding: 1px 5px;\n  border-radius: 4px;\n  letter-spacing: 0.3px;\n}\n\n.ring-node-all {\n  border: 1px solid rgba(255, 255, 255, 0.12);\n  background: rgba(255, 255, 255, 0.03);\n}\n\n.ring-node-all .ring-node-letter {\n  color: var(--text-muted);\n}\n\n.ring-node-all.ring-node-selected {\n  border: 1.5px solid #FAFAFA;\n  background: rgba(255, 255, 255, 0.14);\n}\n\n.ring-node-all.ring-node-selected .ring-node-letter {\n  color: #FAFAFA;\n}\n\n.mesh-target-bar {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 8px;\n  font-size: 11.5px;\n  padding: 8px 12px;\n  background: rgba(255, 255, 255, 0.03);\n  border-radius: 10px;\n  border: 1px solid var(--border-color);\n}\n\n.target-label {\n  color: var(--text-dim);\n  flex-shrink: 0;\n  font-size: 10.5px;\n  text-transform: uppercase;\n  letter-spacing: 0.6px;\n  font-weight: 600;\n}\n\n.target-node-text {\n  font-weight: 700;\n  color: var(--text-main);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  text-align: right;\n  max-width: 65%;\n  font-family: var(--font-mono);\n}\n\n/* =========================================================\n   Stream / Dropzone\n   ========================================================= */\n.dropzone {\n  position: relative;\n  border: 1.5px dashed rgba(255, 255, 255, 0.14);\n  border-radius: 18px;\n  padding: 34px 20px;\n  text-align: center;\n  cursor: pointer;\n  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);\n  background: rgba(255, 255, 255, 0.015);\n}\n\n.dropzone:hover, .dropzone.dragover {\n  border-color: #FAFAFA;\n  background: rgba(255, 255, 255, 0.04);\n  transform: translateY(-1px);\n}\n\n.dropzone-icon-box {\n  width: 48px;\n  height: 48px;\n  border-radius: 14px;\n  background: rgba(255, 255, 255, 0.05);\n  border: 1px solid rgba(255, 255, 255, 0.12);\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  color: var(--text-main);\n  transition: all 0.2s ease;\n  margin-bottom: 2px;\n}\n\n.dropzone:hover .dropzone-icon-box, .dropzone.dragover .dropzone-icon-box {\n  background: rgba(255, 255, 255, 0.12);\n  border-color: #FAFAFA;\n  transform: scale(1.05);\n}\n\n.file-input {\n  position: absolute;\n  top: 0;\n  left: 0;\n  width: 100%;\n  height: 100%;\n  opacity: 0;\n  cursor: pointer;\n}\n\n.dropzone-content {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 10px;\n  pointer-events: none;\n}\n\n.dropzone-text {\n  font-size: 15px;\n  font-weight: 600;\n  color: var(--text-main);\n  letter-spacing: -0.2px;\n}\n\n.dropzone-hint {\n  font-size: 11.5px;\n  color: var(--text-dim);\n}\n\n/* Mascot face compatibility container */\n.mascot-face {\n  display: none !important;\n}\n\n/* =========================================================\n   Transfer Progress Area\n   ========================================================= */\n.transfer-container {\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n  background: rgba(0, 0, 0, 0.4);\n  padding: 16px;\n  border-radius: 14px;\n  border: 1px solid var(--border-color);\n}\n\n.hidden {\n  display: none !important;\n}\n\n.transfer-info {\n  display: flex;\n  justify-content: space-between;\n  align-items: flex-start;\n  gap: 12px;\n}\n\n.transfer-title-group {\n  display: flex;\n  flex-direction: column;\n  gap: 3px;\n  overflow: hidden;\n}\n\n.transfer-file-name {\n  font-size: 13.5px;\n  font-weight: 600;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  max-width: 260px;\n  color: var(--text-main);\n}\n\n.transfer-stats {\n  font-size: 11.5px;\n  color: var(--text-dim);\n  font-family: var(--font-mono);\n}\n\n.transfer-metrics {\n  display: flex;\n  flex-direction: column;\n  align-items: flex-end;\n  gap: 3px;\n}\n\n.transfer-speed {\n  font-size: 13.5px;\n  font-weight: 700;\n  color: var(--text-main);\n  font-variant-numeric: tabular-nums;\n  font-family: var(--font-mono);\n}\n\n.transfer-eta {\n  font-size: 10.5px;\n  color: var(--text-dim);\n  font-family: var(--font-mono);\n}\n\n.progress-bar-bg {\n  width: 100%;\n  height: 6px;\n  background: rgba(255, 255, 255, 0.08);\n  border-radius: 9999px;\n  overflow: hidden;\n}\n\n.progress-bar-fill {\n  height: 100%;\n  background: #FAFAFA;\n  border-radius: 9999px;\n  transition: width 0.15s ease-out;\n}\n\n.transfer-footer {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  font-size: 11.5px;\n  gap: 8px;\n}\n\n.transfer-footer-left {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  overflow: hidden;\n  flex: 1;\n  min-width: 0;\n}\n\n.chunk-badge {\n  font-size: 10.5px;\n  color: var(--text-dim);\n  background: rgba(255, 255, 255, 0.04);\n  padding: 3px 8px;\n  border-radius: 6px;\n  font-family: var(--font-mono);\n  flex-shrink: 0;\n}\n\n.transfer-status-text {\n  color: var(--text-muted);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.btn-cancel-transfer {\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  background: rgba(255, 255, 255, 0.06);\n  border: 1px solid rgba(255, 255, 255, 0.14);\n  color: #FAFAFA;\n  font-size: 11px;\n  font-weight: 700;\n  padding: 4px 10px;\n  border-radius: 8px;\n  cursor: pointer;\n  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);\n  flex-shrink: 0;\n}\n\n.btn-cancel-transfer:hover {\n  background: rgba(239, 68, 68, 0.16);\n  border-color: rgba(239, 68, 68, 0.35);\n  color: #F87171;\n}\n\n.btn-cancel-transfer svg {\n  stroke: currentColor;\n  flex-shrink: 0;\n}\n\n/* =========================================================\n   Incoming Mesh Transfer Notification\n   ========================================================= */\n.incoming-card {\n  border: 1px solid rgba(255, 255, 255, 0.20);\n  background: rgba(24, 24, 27, 0.92);\n  backdrop-filter: blur(28px) saturate(180%);\n  -webkit-backdrop-filter: blur(28px) saturate(180%);\n  box-shadow: 0 12px 36px rgba(0, 0, 0, 0.6);\n  animation: slideDown 0.3s ease-out;\n}\n\n@keyframes slideDown {\n  from { opacity: 0; transform: translateY(-10px); }\n  to { opacity: 1; transform: translateY(0); }\n}\n\n.incoming-header-left {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n\n.btn-dismiss-incoming {\n  background: transparent;\n  border: none;\n  color: var(--text-dim);\n  font-size: 14px;\n  cursor: pointer;\n  padding: 2px 6px;\n  border-radius: 4px;\n  transition: all 0.2s;\n}\n\n.btn-dismiss-incoming:hover {\n  color: var(--text-main);\n  background: rgba(255, 255, 255, 0.1);\n}\n\n.incoming-badge {\n  font-size: 10.5px;\n  font-weight: 700;\n  color: var(--text-main);\n  text-transform: uppercase;\n  letter-spacing: 0.6px;\n}\n\n.incoming-from {\n  font-size: 11.5px;\n  color: var(--text-muted);\n  font-family: var(--font-mono);\n}\n\n.incoming-body {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 12px;\n}\n\n.incoming-info h3 {\n  font-size: 13.5px;\n  font-weight: 700;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  max-width: 280px;\n}\n\n.incoming-info span {\n  font-size: 11.5px;\n  color: var(--text-dim);\n  font-family: var(--font-mono);\n}\n\n.btn-incoming-download {\n  background: #FAFAFA;\n  color: #09090B;\n  font-weight: 800;\n  font-size: 12px;\n  padding: 8px 16px;\n  border-radius: 10px;\n  text-decoration: none;\n  flex-shrink: 0;\n  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);\n}\n\n.btn-incoming-download:hover {\n  background: #E4E4E7;\n  transform: translateY(-1px);\n}\n\n/* =========================================================\n   Files from Host\n   ========================================================= */\n.host-files-list {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  min-height: 50px;\n}\n\n.empty-state {\n  font-size: 12.5px;\n  color: var(--text-dim);\n  text-align: center;\n  padding: 18px 0;\n}\n\n.file-row {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 10px;\n  padding: 10px 14px;\n  background: rgba(255, 255, 255, 0.03);\n  border-radius: 12px;\n  border: 1px solid var(--border-color);\n  transition: background 0.2s;\n}\n\n.file-row:hover {\n  background: rgba(255, 255, 255, 0.05);\n}\n\n.file-row-info {\n  flex: 1;\n  min-width: 0;\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n}\n\n.file-row-name {\n  font-size: 13px;\n  font-weight: 600;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  width: 100%;\n  color: var(--text-main);\n}\n\n.file-row-size {\n  font-size: 10.5px;\n  color: var(--text-dim);\n  font-family: var(--font-mono);\n}\n\n.btn-download {\n  background: #FAFAFA;\n  color: #09090B;\n  font-weight: 800;\n  font-size: 11.5px;\n  padding: 6px 14px;\n  border-radius: 8px;\n  text-decoration: none;\n  transition: all 0.2s;\n  flex-shrink: 0;\n}\n\n.btn-download:hover {\n  background: #E4E4E7;\n  transform: translateY(-1px);\n}\n\n.file-row-actions {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  flex-shrink: 0;\n}\n\n.btn-unshare {\n  background: transparent;\n  color: var(--text-dim);\n  border: 1px solid rgba(255, 255, 255, 0.14);\n  border-radius: 7px;\n  width: 26px;\n  height: 26px;\n  font-size: 13px;\n  font-weight: 700;\n  line-height: 1;\n  cursor: pointer;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n}\n\n.btn-unshare:hover {\n  color: #F87171;\n  border-color: rgba(248, 113, 113, 0.45);\n  background: rgba(248, 113, 113, 0.1);\n}\n\n.btn-icon {\n  background: transparent;\n  border: none;\n  color: var(--text-muted);\n  font-size: 17px;\n  cursor: pointer;\n  padding: 4px;\n  transition: color 0.2s;\n}\n\n.btn-icon:hover {\n  color: var(--text-main);\n}\n\n/* =========================================================\n   Footer\n   ========================================================= */\n.app-footer {\n  text-align: center;\n  font-size: 11px;\n  color: var(--text-dim);\n  padding: 10px 0;\n  letter-spacing: 0.2px;\n}\n\n/* =========================================================\n   Liquid Glass Optical Pairing Overlay Modal\n   ========================================================= */\n.glass-modal-overlay {\n  position: fixed;\n  inset: 0;\n  z-index: 100000;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 24px;\n  opacity: 1;\n  visibility: visible;\n  transition: opacity 0.35s cubic-bezier(0.16, 1, 0.3, 1), visibility 0.35s;\n}\n\n.glass-modal-overlay.hidden {\n  opacity: 0;\n  visibility: hidden;\n  pointer-events: none;\n}\n\n.glass-modal-backdrop {\n  position: absolute;\n  inset: 0;\n  background: rgba(0, 0, 0, 0.78);\n  backdrop-filter: blur(40px) saturate(180%);\n  -webkit-backdrop-filter: blur(40px) saturate(180%);\n  cursor: pointer;\n}\n\n.glass-modal-container {\n  position: relative;\n  z-index: 2;\n  max-width: 420px;\n  width: 100%;\n  animation: glassModalPop 0.4s cubic-bezier(0.16, 1, 0.3, 1);\n}\n\n@keyframes glassModalPop {\n  0% {\n    opacity: 0;\n    transform: scale(0.94) translateY(18px);\n  }\n  100% {\n    opacity: 1;\n    transform: scale(1) translateY(0);\n  }\n}\n\n.glass-modal-panel {\n  position: relative;\n  overflow: hidden;\n  background: linear-gradient(145deg, rgba(255, 255, 255, 0.14) 0%, rgba(28, 30, 38, 0.52) 38%, rgba(10, 11, 15, 0.82) 100%);\n  backdrop-filter: blur(44px) saturate(190%);\n  -webkit-backdrop-filter: blur(44px) saturate(190%);\n  border: 1px solid rgba(255, 255, 255, 0.28);\n  border-radius: 32px;\n  padding: 16px 20px 22px;\n  box-shadow:\n    0 35px 80px rgba(0, 0, 0, 0.85),\n    inset 0 1px 0 rgba(255, 255, 255, 0.42),\n    inset 0 -1px 0 rgba(255, 255, 255, 0.14);\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 14px;\n  transition: box-shadow 0.35s ease;\n}\n\n.glass-modal-panel::before {\n  content: \"\";\n  position: absolute;\n  top: -20%;\n  left: -18%;\n  width: 65%;\n  height: 140%;\n  background: linear-gradient(115deg, rgba(255, 255, 255, 0.12) 0%, rgba(255, 255, 255, 0.02) 55%, rgba(255, 255, 255, 0) 100%);\n  transform: skewX(-18deg);\n  pointer-events: none;\n}\n\n.glass-modal-panel::after {\n  content: \"\";\n  position: absolute;\n  top: -1px;\n  right: 18%;\n  width: 72px;\n  height: 3px;\n  border-radius: 9999px;\n  background: radial-gradient(circle, rgba(255, 255, 255, 0.95) 0%, rgba(255, 255, 255, 0) 72%);\n  pointer-events: none;\n}\n\n/* Monochromatic Theme Box Shadows */\n.glass-modal-panel.theme-obsidian {\n  box-shadow: 0 35px 80px rgba(0, 0, 0, 0.95), 0 0 1px 1px rgba(255, 255, 255, 0.14);\n}\n\n.glass-modal-panel.theme-titanium {\n  box-shadow: 0 35px 80px rgba(0, 0, 0, 0.85), 0 0 1px 1px rgba(255, 255, 255, 0.22);\n}\n\n.glass-modal-panel.theme-paper {\n  box-shadow: 0 35px 80px rgba(0, 0, 0, 0.65), 0 0 1px 1px rgba(255, 255, 255, 0.35);\n}\n\n.glass-modal-header {\n  width: 100%;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n}\n\n.glass-theme-picker {\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  background: rgba(255, 255, 255, 0.06);\n  border: 1px solid rgba(255, 255, 255, 0.10);\n  padding: 4px;\n  border-radius: 9999px;\n}\n\n.glass-theme-btn {\n  background: transparent;\n  border: none;\n  color: var(--text-dim);\n  font-size: 11px;\n  font-weight: 700;\n  padding: 5px 12px;\n  border-radius: 9999px;\n  cursor: pointer;\n  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);\n}\n\n.glass-theme-btn:hover {\n  color: #FAFAFA;\n}\n\n.glass-theme-btn.active {\n  background: rgba(255, 255, 255, 0.18);\n  color: #FAFAFA;\n  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.4);\n}\n\n.glass-close-btn {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  width: 32px;\n  height: 32px;\n  background: rgba(255, 255, 255, 0.06);\n  border: 1px solid rgba(255, 255, 255, 0.12);\n  border-radius: 50%;\n  color: var(--text-dim);\n  cursor: pointer;\n  transition: all 0.2s ease;\n}\n\n.glass-close-btn:hover {\n  color: #FAFAFA;\n  background: rgba(255, 255, 255, 0.16);\n  transform: scale(1.06);\n}\n\n.glass-card-viewport {\n  width: 100%;\n  display: flex;\n  justify-content: center;\n}\n\n.glass-qr-wrapper {\n  max-width: 320px;\n  width: 100%;\n  border-radius: 26px;\n  overflow: hidden;\n  box-shadow: 0 20px 48px rgba(0, 0, 0, 0.7);\n  transition: transform 0.3s ease;\n}\n\n.glass-qr-wrapper:hover {\n  transform: translateY(-2px);\n}\n\n.glass-qr-wrapper img {\n  display: block;\n  width: 100%;\n  height: auto;\n}\n\n.glass-qr-canvas {\n  display: block;\n  width: 320px;\n  max-width: 100%;\n  height: 410px;\n}\n\n.glass-modal-footer {\n  text-align: center;\n}\n\n.glass-hint {\n  font-size: 11px;\n  color: var(--text-dim);\n  font-family: var(--font-mono);\n  letter-spacing: 0.2px;\n}\n\n/* =========================================================\n   Responsive Cross-Device Layout (Apple HIG Grounded)\n   Mobile (<= 640px), Small Phones (<= 380px)\n   ========================================================= */\n\n@media (max-width: 640px) {\n  .app-container {\n    gap: 14px;\n    max-width: 100%;\n  }\n\n  .app-header {\n    padding: 10px 14px;\n    border-radius: 16px;\n  }\n\n  .brand {\n    gap: 10px;\n  }\n\n  .brand-icon {\n    width: 28px;\n    height: 28px;\n    border-radius: 8px;\n  }\n\n  .logo-badge {\n    font-size: 16.5px;\n  }\n\n  .brand-sub {\n    font-size: 9px;\n  }\n\n  /* Compact Pair QR button: Icon only on small mobile to preserve layout */\n  #openQrModalBtn {\n    padding: 6px 9px;\n    border-radius: 8px;\n  }\n\n  #openQrModalBtn .btn-text {\n    display: none;\n  }\n\n  .connection-status {\n    padding: 5px 9px;\n    font-size: 11px;\n    max-width: 140px;\n  }\n\n  .connection-status #hostName {\n    max-width: 95px;\n  }\n\n  .card {\n    padding: 16px 14px;\n    border-radius: 18px;\n    gap: 12px;\n    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.35);\n  }\n\n  .card-header h2 {\n    font-size: 15px;\n  }\n\n  .my-slot-badge {\n    font-size: 10px;\n    padding: 3px 8px;\n    border-radius: 6px;\n  }\n\n  /* Responsive 3x2 Grid for Ring Topology:\n     Row 1: [ U ] [ X ] [ I ]\n     Row 2: [ O ] [ M ] [ ALL ]\n     Equal widths, equal heights, zero wrapping! */\n  .mesh-ring {\n    grid-template-columns: repeat(3, 1fr);\n    gap: 8px;\n  }\n\n  .ring-node {\n    min-height: 70px;\n    padding: 8px 4px;\n    border-radius: 12px;\n  }\n\n  .ring-node-letter {\n    font-size: 14px;\n  }\n\n  .ring-node-letter-all {\n    font-size: 11.5px !important;\n  }\n\n  .ring-node-device {\n    font-size: 9.5px;\n  }\n\n  .mesh-target-bar {\n    padding: 8px 10px;\n    font-size: 11px;\n    border-radius: 8px;\n  }\n\n  .target-node-text {\n    max-width: 60%;\n    font-size: 11px;\n  }\n\n  .dropzone {\n    padding: 22px 14px;\n    border-radius: 14px;\n  }\n\n  .dropzone-text {\n    font-size: 13.5px;\n  }\n\n  .dropzone-hint {\n    font-size: 10.5px;\n  }\n\n  .transfer-container {\n    padding: 12px;\n    border-radius: 12px;\n    gap: 10px;\n  }\n\n  .transfer-file-name {\n    max-width: 160px;\n    font-size: 12.5px;\n  }\n\n  .file-row {\n    padding: 9px 12px;\n    border-radius: 10px;\n  }\n\n  .file-row-name {\n    font-size: 12.5px;\n  }\n\n  .btn-download {\n    padding: 6px 12px;\n    font-size: 11px;\n    border-radius: 7px;\n  }\n\n  .glass-modal-overlay {\n    padding: 12px;\n  }\n\n  .glass-modal-panel {\n    border-radius: 24px;\n    padding: 14px 14px 18px;\n    gap: 12px;\n  }\n\n  .glass-qr-wrapper {\n    max-width: 275px;\n    border-radius: 20px;\n  }\n\n  .glass-theme-btn {\n    font-size: 10px;\n    padding: 4px 8px;\n  }\n\n  .app-footer {\n    font-size: 10px;\n    padding: 8px 0 max(20px, env(safe-area-inset-bottom, 20px));\n  }\n}\n\n/* Extra Compact Phones (iPhone SE, small Androids <= 380px) */\n@media (max-width: 380px) {\n  body {\n    padding: max(10px, env(safe-area-inset-top, 10px))\n             10px\n             max(24px, env(safe-area-inset-bottom, 24px))\n             10px;\n  }\n\n  .app-header {\n    padding: 8px 10px;\n  }\n\n  .brand-icon {\n    width: 24px;\n    height: 24px;\n  }\n\n  .logo-badge {\n    font-size: 15px;\n  }\n\n  .connection-status {\n    max-width: 115px;\n    padding: 4px 6px;\n    font-size: 10px;\n  }\n\n  .connection-status #hostName {\n    max-width: 75px;\n  }\n\n  .mesh-ring {\n    gap: 6px;\n  }\n\n  .ring-node {\n    min-height: 64px;\n    padding: 6px 2px;\n    border-radius: 10px;\n  }\n\n  .ring-node-letter {\n    font-size: 13px;\n  }\n\n  .ring-node-letter-all {\n    font-size: 10.5px !important;\n  }\n\n  .ring-node-device {\n    font-size: 9px;\n  }\n}\n\n\n/* =========================================================\n   Multi-Video & Batch Queue Stream Components\n   ========================================================= */\n.dropzone-quick-actions {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 8px;\n  margin-top: 6px;\n  position: relative;\n  z-index: 10;\n  pointer-events: auto;\n  flex-wrap: wrap;\n}\n\n.btn-picker-pill {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  background: rgba(255, 255, 255, 0.08);\n  border: 1px solid rgba(255, 255, 255, 0.16);\n  color: #FAFAFA;\n  font-size: 11.5px;\n  font-weight: 700;\n  padding: 6px 14px;\n  border-radius: 9999px;\n  cursor: pointer;\n  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);\n  letter-spacing: -0.1px;\n}\n\n.btn-picker-pill:hover {\n  background: rgba(255, 255, 255, 0.16);\n  border-color: rgba(255, 255, 255, 0.30);\n  transform: translateY(-1px);\n}\n\n.btn-picker-pill.outline {\n  background: transparent;\n  border-color: rgba(255, 255, 255, 0.10);\n  color: var(--text-muted);\n}\n\n.btn-picker-pill.outline:hover {\n  background: rgba(255, 255, 255, 0.06);\n  border-color: rgba(255, 255, 255, 0.20);\n  color: #FAFAFA;\n}\n\n.dropzone-busy {\n  pointer-events: none !important;\n  opacity: 0.55;\n  filter: grayscale(0.5);\n  cursor: wait !important;\n}\n\n/* Batch Summary & Global Progress */\n.batch-summary-bar {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  padding-bottom: 12px;\n  border-bottom: 1px solid var(--border-color);\n}\n\n.batch-summary-info {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 8px;\n}\n\n.batch-title-row {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n\n.batch-title {\n  font-size: 11.5px;\n  font-weight: 700;\n  text-transform: uppercase;\n  letter-spacing: 0.6px;\n  color: var(--text-main);\n}\n\n.batch-count-badge {\n  font-family: var(--font-mono);\n  font-size: 10.5px;\n  font-weight: 700;\n  padding: 2px 7px;\n  background: rgba(255, 255, 255, 0.08);\n  border-radius: 6px;\n  color: var(--text-main);\n}\n\n.batch-progress-stats {\n  font-size: 11px;\n  color: var(--text-muted);\n  font-family: var(--font-mono);\n}\n\n.batch-progress-bg {\n  height: 5px;\n  background: rgba(255, 255, 255, 0.06);\n}\n\n.batch-fill {\n  background: #A1A1AA;\n}\n\n/* Detailed Queue List */\n.queue-list-wrapper {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  margin-top: 4px;\n  padding-top: 10px;\n  border-top: 1px solid var(--border-color);\n}\n\n.queue-list-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 8px;\n}\n\n.queue-list-title {\n  font-size: 10.5px;\n  text-transform: uppercase;\n  letter-spacing: 0.6px;\n  color: var(--text-dim);\n  font-weight: 700;\n}\n\n.btn-retry-failed {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  background: rgba(239, 68, 68, 0.12);\n  border: 1px solid rgba(239, 68, 68, 0.28);\n  color: #F87171;\n  font-size: 10px;\n  font-weight: 700;\n  padding: 3px 8px;\n  border-radius: 6px;\n  cursor: pointer;\n  transition: all 0.2s ease;\n}\n\n.btn-retry-failed:hover {\n  background: rgba(239, 68, 68, 0.22);\n  border-color: rgba(239, 68, 68, 0.45);\n}\n\n.queue-items-list {\n  display: flex;\n  flex-direction: column;\n  gap: 5px;\n  max-height: 180px;\n  overflow-y: auto;\n  padding-right: 4px;\n}\n\n.queue-items-list::-webkit-scrollbar {\n  width: 4px;\n}\n\n.queue-items-list::-webkit-scrollbar-thumb {\n  background: rgba(255, 255, 255, 0.14);\n  border-radius: 4px;\n}\n\n.queue-item {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 10px;\n  padding: 6px 10px;\n  background: rgba(255, 255, 255, 0.02);\n  border: 1px solid var(--border-color);\n  border-radius: 9px;\n  transition: all 0.15s ease;\n}\n\n.queue-item.active {\n  border-color: rgba(255, 255, 255, 0.24);\n  background: rgba(255, 255, 255, 0.06);\n}\n\n.queue-item-info {\n  flex: 1;\n  min-width: 0;\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n}\n\n.queue-item-name {\n  font-size: 12px;\n  font-weight: 600;\n  color: var(--text-main);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.queue-item-size {\n  font-size: 9.5px;\n  color: var(--text-dim);\n  font-family: var(--font-mono);\n}\n\n.queue-status-pill {\n  font-size: 9.5px;\n  font-weight: 700;\n  padding: 2px 7px;\n  border-radius: 5px;\n  font-family: var(--font-mono);\n  flex-shrink: 0;\n}\n\n.queue-status-pill.waiting {\n  background: rgba(255, 255, 255, 0.04);\n  color: var(--text-dim);\n}\n\n.queue-status-pill.uploading {\n  background: rgba(255, 255, 255, 0.14);\n  color: #FAFAFA;\n}\n\n.queue-status-pill.done {\n  background: rgba(34, 197, 94, 0.12);\n  color: #22C55E;\n  border: 1px solid rgba(34, 197, 94, 0.25);\n}\n\n.queue-status-pill.failed {\n  background: rgba(239, 68, 68, 0.12);\n  color: #F87171;\n  border: 1px solid rgba(239, 68, 68, 0.25);\n}\n",
  "app.js": "const CHUNK_SIZE = 4 * 1024 * 1024; // 4MB Chunks\n\nconst dropzone = document.getElementById('dropzone');\nconst fileInput = document.getElementById('fileInput');\nconst mediaInput = document.getElementById('mediaInput');\nconst pickMediaBtn = document.getElementById('pickMediaBtn');\nconst pickFilesBtn = document.getElementById('pickFilesBtn');\nconst batchSummaryBar = document.getElementById('batchSummaryBar');\nconst batchCountBadge = document.getElementById('batchCountBadge');\nconst batchProgressStats = document.getElementById('batchProgressStats');\nconst batchProgressBar = document.getElementById('batchProgressBar');\nconst queueListWrapper = document.getElementById('queueListWrapper');\nconst queueItemsList = document.getElementById('queueItemsList');\nconst retryFailedBtn = document.getElementById('retryFailedBtn');\nconst wakeLockVideo = document.getElementById('wakeLockVideo');\nconst dropzoneHintText = document.getElementById('dropzoneHintText');\nconst hostNameEl = document.getElementById('hostName');\nconst mascotFace = document.getElementById('mascotFace');\nconst transferContainer = document.getElementById('transferContainer');\nconst transferFileName = document.getElementById('transferFileName');\nconst transferStats = document.getElementById('transferStats');\nconst transferSpeed = document.getElementById('transferSpeed');\nconst transferEta = document.getElementById('transferEta');\nconst progressBar = document.getElementById('progressBar');\nconst transferChunks = document.getElementById('transferChunks');\nconst transferStatus = document.getElementById('transferStatus');\nconst cancelTransferBtn = document.getElementById('cancelTransferBtn');\nconst hostFilesList = document.getElementById('hostFilesList');\n\nlet currentUploadAbortController = null;\nlet isCurrentTransferCancelled = false;\nlet currentUploadFileId = null;\nconst refreshFilesBtn = document.getElementById('refreshFilesBtn');\n\n// UXIOM Mesh DOM Elements\nconst mySlotBadge = document.getElementById('mySlotBadge');\nconst meshRing = document.getElementById('meshRing');\nconst targetNodeText = document.getElementById('targetNodeText');\nconst dropzoneActionText = document.getElementById('dropzoneActionText');\nconst incomingTransferCard = document.getElementById('incomingTransferCard');\nconst incomingFromText = document.getElementById('incomingFromText');\nconst incomingFileName = document.getElementById('incomingFileName');\nconst incomingFileSize = document.getElementById('incomingFileSize');\nconst incomingDownloadBtn = document.getElementById('incomingDownloadBtn');\nconst dismissIncomingBtn = document.getElementById('dismissIncomingBtn');\n\n// Liquid Glass Dynamic Island Elements\nconst dynamicIsland = document.getElementById('dynamicIsland');\nconst islandFromNode = document.getElementById('islandFromNode');\nconst islandSpeed = document.getElementById('islandSpeed');\nconst islandFileName = document.getElementById('islandFileName');\nconst islandProgressBar = document.getElementById('islandProgressBar');\nconst islandPercent = document.getElementById('islandPercent');\nconst islandCompleteName = document.getElementById('islandCompleteName');\nconst islandCompleteSize = document.getElementById('islandCompleteSize');\nconst islandOpenFolderBtn = document.getElementById('islandOpenFolderBtn');\nconst islandDismissBtn = document.getElementById('islandDismissBtn');\n\n// Dynamic Island State & Audio\nlet islandRevertTimer = null;\nlet currentHostTransfer = null;\nlet lastReceivedFile = null;\nlet islandAudioCtx = null;\n\n// UXIOM Mesh State\nlet myClientId = localStorage.getItem('udrop_mesh_client_id');\nif (!myClientId) {\n  myClientId = 'client_' + (crypto.randomUUID ? crypto.randomUUID() : Math.random().toString(36).substring(2, 11));\n  localStorage.setItem('udrop_mesh_client_id', myClientId);\n}\n\nlet mySlot = null; // 'X', 'I', 'O', 'M' or 'U'\nlet targetSlot = 'U'; // Default recipient: Host [ U ]\nlet currentRingState = [];\n\nfunction formatBytes(bytes) {\n  if (bytes === 0) return '0 B';\n  const k = 1024;\n  const sizes = ['B', 'KB', 'MB', 'GB', 'TB'];\n  const i = Math.floor(Math.log(bytes) / Math.log(k));\n  return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];\n}\n\nfunction escapeHtml(str) {\n  return String(str || '').replace(/[&<>\"']/g, (ch) => {\n    switch (ch) {\n      case '&': return '&amp;';\n      case '<': return '&lt;';\n      case '>': return '&gt;';\n      case '\"': return '&quot;';\n      case \"'\": return '&#39;';\n      default: return ch;\n    }\n  });\n}\n\nfunction isLocalHostPage() {\n  const h = window.location.hostname;\n  return h === 'localhost' || h === '127.0.0.1' || h === '::1' || h === '[::1]';\n}\n\n// 1. Fetch Host Device Info\nasync function checkHostConnection() {\n  try {\n    const res = await fetch('/api/info');\n    if (!res.ok) throw new Error();\n    const data = await res.json();\n    hostNameEl.textContent = data.hostname;\n    if (hostNameEl.parentElement) {\n      hostNameEl.parentElement.title = `Connected to ${data.hostname} (${data.platform})`;\n    }\n  } catch (err) {\n    hostNameEl.textContent = 'Connecting...';\n  }\n}\n\n// 2. Fetch Available Files from Host\nasync function loadHostFiles() {\n  try {\n    const res = await fetch('/api/files');\n    const files = await res.json();\n    if (!files || files.length === 0) {\n      hostFilesList.innerHTML = '<p class=\"empty-state\">No files currently shared by the host.</p>';\n      return;\n    }\n\n    const canUnshare = isLocalHostPage();\n    hostFilesList.innerHTML = files.map(f => {\n      const safeName = escapeHtml(f.name);\n      const safeId = encodeURIComponent(f.id);\n      return `\n      <div class=\"file-row\">\n        <div class=\"file-row-info\">\n          <span class=\"file-row-name\" title=\"${safeName}\">${safeName}</span>\n          <span class=\"file-row-size\">${formatBytes(f.size)}</span>\n        </div>\n        <div class=\"file-row-actions\">\n          <a href=\"/api/download/${safeId}\" class=\"btn-download\" download>Download</a>\n          ${canUnshare ? `<button type=\"button\" class=\"btn-unshare\" data-unshare-id=\"${safeId}\" title=\"Remove from shared list\">&times;</button>` : ''}\n        </div>\n      </div>\n    `;\n    }).join('');\n\n    if (canUnshare) {\n      hostFilesList.querySelectorAll('.btn-unshare').forEach(btn => {\n        btn.addEventListener('click', async () => {\n          const id = btn.getAttribute('data-unshare-id');\n          if (!id) return;\n          try {\n            await fetch(`/api/outbound/${id}`, { method: 'DELETE' });\n            loadHostFiles();\n          } catch (e) {}\n        });\n      });\n    }\n  } catch (err) {\n    hostFilesList.innerHTML = '<p class=\"empty-state\">Failed to load host files.</p>';\n  }\n}\n\n// 3. UXIOM Mesh Ring Management\nasync function joinMesh() {\n  try {\n    const isHost = isLocalHostPage();\n    const res = await fetch('/api/mesh/join', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({\n        clientId: myClientId,\n        userAgent: navigator.userAgent,\n        isHostDashboard: isHost\n      })\n    });\n    if (res.ok) {\n      const data = await res.json();\n      if (data.success) {\n        mySlot = data.slot;\n        if (mySlotBadge) {\n          mySlotBadge.textContent = mySlot === 'U' ? 'Assigned: [ U ] Host' : `Assigned: [ ${mySlot} ]`;\n          mySlotBadge.classList.add('active');\n        }\n        if (data.ring) {\n          renderRing(data.ring);\n        }\n      }\n    }\n  } catch (err) {\n    console.warn('Mesh registration error:', err);\n  }\n}\n\nfunction renderRing(ring) {\n  if (!meshRing) return;\n  currentRingState = ring || [];\n  meshRing.innerHTML = '';\n\n  ring.forEach(node => {\n    const isSelf = (node.slot === mySlot);\n    const isTarget = (node.slot === targetSlot);\n    const safeNodeName = escapeHtml(node.assigned ? node.name : 'Empty');\n    const safeSlot = escapeHtml(node.slot);\n\n    const nodeEl = document.createElement('div');\n    nodeEl.className = 'ring-node';\n    if (node.assigned) nodeEl.classList.add('ring-node-active');\n    if (isSelf) nodeEl.classList.add('ring-node-self');\n    if (isTarget) nodeEl.classList.add('ring-node-selected');\n\n    nodeEl.innerHTML = `\n      ${isSelf ? '<span class=\"self-tag\">YOU</span>' : ''}\n      <span class=\"ring-node-letter\">[ ${safeSlot} ]</span>\n      <span class=\"ring-node-device\" title=\"${safeNodeName}\">${safeNodeName}</span>\n    `;\n\n    // Only allow selecting valid targets (can't target oneself)\n    if (!isSelf && node.assigned) {\n      nodeEl.addEventListener('click', () => {\n        selectTarget(node.slot, `[ ${node.slot} ] ${node.name}`);\n      });\n    } else if (!isSelf && !node.assigned && node.slot === 'U') {\n      // Host slot fallback\n      nodeEl.addEventListener('click', () => {\n        selectTarget('U', '[ U ] Master Host');\n      });\n    }\n\n    meshRing.appendChild(nodeEl);\n  });\n\n  // Swarm / Broadcast Node [ ALL ]\n  const isSwarmTarget = (targetSlot === 'ALL');\n  const swarmEl = document.createElement('div');\n  swarmEl.className = 'ring-node ring-node-all ring-node-active' + (isSwarmTarget ? ' ring-node-selected' : '');\n  swarmEl.innerHTML = `\n    <span class=\"ring-node-letter ring-node-letter-all\">[ ALL ]</span>\n    <span class=\"ring-node-device\">Swarm All</span>\n  `;\n  swarmEl.addEventListener('click', () => {\n    selectTarget('ALL', '[ ALL ] All Mesh Devices (Swarm Broadcast)');\n  });\n  meshRing.appendChild(swarmEl);\n}\n\nfunction selectTarget(slot, label) {\n  targetSlot = slot;\n  if (targetNodeText) targetNodeText.textContent = label;\n  if (dropzoneActionText) {\n    dropzoneActionText.textContent = `Tap or Drag to Beam to ${label}`;\n  }\n  renderRing(currentRingState);\n}\n\n// 4. SSE Real-Time Event Stream\nfunction connectMeshEvents() {\n  const eventSource = new EventSource('/api/mesh/events');\n\n  eventSource.onmessage = (e) => {\n    try {\n      const data = JSON.parse(e.data);\n      if (data.type === 'ring_update') {\n        const prevCount = currentRingState.filter(n => n.assigned && !n.isHost).length;\n        const nextCount = Array.isArray(data.ring) ? data.ring.filter(n => n.assigned && !n.isHost).length : 0;\n        renderRing(data.ring);\n        if (nextCount > prevCount) {\n          dismantleModalOnConnect('Device Connected');\n        }\n      } else if (data.type === 'qr_scanned') {\n        dismantleModalOnConnect('Phone Redirecting...');\n      } else if (data.type === 'incoming_mesh_transfer') {\n        handleIncomingMeshTransfer(data.transfer);\n      } else if (data.type === 'host_transfer_start') {\n        handleHostTransferStart(data);\n      } else if (data.type === 'host_transfer_progress') {\n        handleHostTransferProgress(data);\n      } else if (data.type === 'host_transfer_complete') {\n        handleHostTransferComplete(data);\n      } else if (data.type === 'host_transfer_cancel') {\n        handleHostTransferCancel(data);\n      } else if (data.type === 'outbound_updated') {\n        loadHostFiles();\n      } else if (data.type === 'open_qr_modal') {\n        openQrModal();\n      }\n    } catch (err) {\n      console.error('SSE Message error:', err);\n    }\n  };\n\n  eventSource.onerror = () => {\n    // Browser auto-reconnects SSE\n  };\n}\n\n// =========================================================\n// Apple Liquid Glass Dynamic Island Logic\n// =========================================================\nfunction setIslandState(state) {\n  if (!dynamicIsland) return;\n  dynamicIsland.classList.remove('state-idle', 'state-receiving', 'state-complete');\n  dynamicIsland.classList.add(state);\n}\n\nfunction playSuccessChime() {\n  try {\n    const AudioCtx = window.AudioContext || window.webkitAudioContext;\n    if (!AudioCtx) return;\n    if (!islandAudioCtx) islandAudioCtx = new AudioCtx();\n    if (islandAudioCtx.state === 'suspended') {\n      islandAudioCtx.resume();\n    }\n    const now = islandAudioCtx.currentTime;\n\n    const playTone = (freq, start, duration, gainVal = 0.16) => {\n      const osc = islandAudioCtx.createOscillator();\n      const gain = islandAudioCtx.createGain();\n      osc.type = 'sine';\n      osc.frequency.setValueAtTime(freq, start);\n      gain.gain.setValueAtTime(0.001, start);\n      gain.gain.linearRampToValueAtTime(gainVal, start + 0.02);\n      gain.gain.exponentialRampToValueAtTime(0.0001, start + duration);\n      osc.connect(gain);\n      gain.connect(islandAudioCtx.destination);\n      osc.start(start);\n      osc.stop(start + duration);\n    };\n\n    // Apple-style two-tone warm chime (E5 -> C6)\n    playTone(659.25, now, 0.22, 0.15);\n    playTone(1046.50, now + 0.10, 0.40, 0.20);\n  } catch (err) {\n    // Silent fail if browser prevents unmuted audio without prior touch\n  }\n}\n\nfunction handleHostTransferStart(data) {\n  if (islandRevertTimer) clearTimeout(islandRevertTimer);\n\n  currentHostTransfer = {\n    fileId: data.fileId,\n    fileName: data.fileName,\n    fileSize: data.fileSize || 0,\n    totalChunks: data.totalChunks || 1,\n    fromSlot: data.fromSlot || 'Node',\n    queueIndex: data.queueIndex || 1,\n    totalFiles: data.totalFiles || 1,\n    startTime: Date.now(),\n    lastBytes: 0,\n    lastTime: Date.now()\n  };\n\n  if (data.totalFiles && data.totalFiles > 1) {\n    if (islandFileName) islandFileName.textContent = `[${data.queueIndex}/${data.totalFiles}] ${data.fileName}`;\n    if (islandFromNode) islandFromNode.textContent = `[ ${data.fromSlot || 'Node'} ] Queue ${data.queueIndex}/${data.totalFiles}`;\n  } else {\n    if (islandFileName) islandFileName.textContent = data.fileName;\n    if (islandFromNode) islandFromNode.textContent = `[ ${data.fromSlot || 'Node'} ]`;\n  }\n\n  if (islandSpeed) islandSpeed.textContent = 'Streaming...';\n  if (islandProgressBar) islandProgressBar.style.width = '0%';\n  if (islandPercent) islandPercent.textContent = '0%';\n\n  setIslandState('state-receiving');\n}\n\nfunction handleHostTransferProgress(data) {\n  if (!currentHostTransfer || currentHostTransfer.fileId !== data.fileId) {\n    currentHostTransfer = {\n      fileId: data.fileId,\n      fileSize: data.totalBytes || 0,\n      totalChunks: data.totalChunks || 1,\n      startTime: Date.now(),\n      lastBytes: 0,\n      lastTime: Date.now()\n    };\n  }\n\n  const totalBytes = data.totalBytes || currentHostTransfer.fileSize || 0;\n  const hasByteProgress = (typeof data.receivedBytes === 'number' && totalBytes > 0);\n  const percent = hasByteProgress\n    ? Math.min(100, Math.round((data.receivedBytes / totalBytes) * 100))\n    : Math.min(100, Math.round((data.receivedTotal / (data.totalChunks || 1)) * 100));\n\n  if (islandProgressBar) islandProgressBar.style.width = `${percent}%`;\n  if (islandPercent) islandPercent.textContent = `${percent}%`;\n\n  const currentBytes = hasByteProgress\n    ? data.receivedBytes\n    : (currentHostTransfer.fileSize ? (data.receivedTotal / currentHostTransfer.totalChunks) * currentHostTransfer.fileSize : 0);\n\n  if (currentBytes > 0) {\n    const now = Date.now();\n    const elapsed = (now - currentHostTransfer.lastTime) / 1000;\n    if (elapsed >= 0.4) {\n      const delta = currentBytes - currentHostTransfer.lastBytes;\n      const speedMb = (delta / (1024 * 1024 * elapsed)).toFixed(1);\n      if (islandSpeed && Number(speedMb) > 0) islandSpeed.textContent = `${speedMb} MB/s`;\n      currentHostTransfer.lastBytes = currentBytes;\n      currentHostTransfer.lastTime = now;\n    }\n  }\n}\n\nfunction handleHostTransferCancel(data) {\n  if (!currentHostTransfer || currentHostTransfer.fileId === data.fileId) {\n    currentHostTransfer = null;\n    if (islandRevertTimer) clearTimeout(islandRevertTimer);\n    setIslandState('state-idle');\n  }\n}\n\nfunction handleHostTransferComplete(data) {\n  lastReceivedFile = {\n    fileName: data.fileName,\n    filePath: data.filePath,\n    fileSize: data.fileSize\n  };\n\n  if (islandCompleteName) islandCompleteName.textContent = data.fileName;\n  if (islandCompleteSize) islandCompleteSize.textContent = formatBytes(data.fileSize);\n\n  setIslandState('state-complete');\n  playSuccessChime();\n\n  // Refresh files list in dashboard\n  loadHostFiles();\n\n  // Return to idle state after 8 seconds\n  if (islandRevertTimer) clearTimeout(islandRevertTimer);\n  islandRevertTimer = setTimeout(() => {\n    setIslandState('state-idle');\n  }, 8000);\n}\n\n// Dynamic Island Button Listeners\nif (islandOpenFolderBtn) {\n  islandOpenFolderBtn.addEventListener('click', async (e) => {\n    e.stopPropagation();\n    try {\n      const origHtml = islandOpenFolderBtn.innerHTML;\n      islandOpenFolderBtn.innerHTML = `\n        <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><polyline points=\"20 6 9 17 4 12\"></polyline></svg>\n        <span>Opened!</span>\n      `;\n      await fetch('/api/open-file', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({\n          filePath: lastReceivedFile?.filePath,\n          fileName: lastReceivedFile?.fileName\n        })\n      });\n      setTimeout(() => {\n        islandOpenFolderBtn.innerHTML = origHtml;\n      }, 2000);\n    } catch (err) {\n      console.warn('Failed to open file in Explorer:', err);\n    }\n  });\n}\n\nif (islandDismissBtn) {\n  islandDismissBtn.addEventListener('click', (e) => {\n    e.stopPropagation();\n    if (islandRevertTimer) clearTimeout(islandRevertTimer);\n    setIslandState('state-idle');\n  });\n}\n\nconst openIslandPopoutBtn = document.getElementById('openIslandPopoutBtn');\nif (openIslandPopoutBtn) {\n  openIslandPopoutBtn.addEventListener('click', () => {\n    window.open('/island', 'uDropIsland', 'width=520,height=160,menubar=no,toolbar=no,location=no,status=no');\n  });\n}\n\nif (dynamicIsland) {\n  dynamicIsland.addEventListener('click', (e) => {\n    // If clicked on [ U ] badge in idle state, open Liquid Glass QR modal\n    if (e.target && e.target.classList.contains('island-badge')) {\n      e.stopPropagation();\n      openQrModal();\n      return;\n    }\n    // If clicked while in idle state, open uDrop download folder\n    if (dynamicIsland.classList.contains('state-idle')) {\n      fetch('/api/open-folder', { method: 'POST' }).catch(() => {});\n    }\n  });\n}\n\n// =========================================================\n// Apple Liquid Glass Optical Pairing Modal Logic\n// =========================================================\nconst qrGlassModal = document.getElementById('qrGlassModal');\nconst openQrModalBtn = document.getElementById('openQrModalBtn');\nconst closeQrModalBtn = document.getElementById('closeQrModalBtn');\nconst qrModalBackdrop = document.getElementById('qrModalBackdrop');\nconst glassQrCanvas = document.getElementById('glassQrCanvas');\nconst glassModalPanel = document.getElementById('glassModalPanel');\nconst glassThemeBtns = document.querySelectorAll('.glass-theme-btn');\n\nlet activeModalTheme = 'obsidian';\nlet kineticModalQr = (glassQrCanvas && typeof window.createKineticQr === 'function')\n  ? window.createKineticQr(glassQrCanvas, { theme: activeModalTheme })\n  : null;\nlet isDismantlingModal = false;\n\nfunction openQrModal() {\n  if (!qrGlassModal) return;\n  isDismantlingModal = false;\n  qrGlassModal.classList.remove('hidden');\n  qrGlassModal.setAttribute('aria-hidden', 'false');\n  document.body.style.overflow = 'hidden';\n  if (kineticModalQr) {\n    kineticModalQr.assemble({ theme: activeModalTheme });\n  }\n}\n\nfunction closeQrModal() {\n  if (!qrGlassModal) return;\n  isDismantlingModal = false;\n  qrGlassModal.classList.add('hidden');\n  qrGlassModal.setAttribute('aria-hidden', 'true');\n  document.body.style.overflow = '';\n}\n\nfunction dismantleModalOnConnect(label) {\n  if (!qrGlassModal || qrGlassModal.classList.contains('hidden') || isDismantlingModal) return;\n  isDismantlingModal = true;\n  if (kineticModalQr) {\n    kineticModalQr.disassemble(label || 'Device Connected', () => {\n      setTimeout(() => closeQrModal(), 360);\n    });\n  } else {\n    closeQrModal();\n  }\n}\n\nif (openQrModalBtn) {\n  openQrModalBtn.addEventListener('click', openQrModal);\n}\n\nif (closeQrModalBtn) {\n  closeQrModalBtn.addEventListener('click', closeQrModal);\n}\n\nif (qrModalBackdrop) {\n  qrModalBackdrop.addEventListener('click', closeQrModal);\n}\n\nwindow.addEventListener('keydown', (e) => {\n  if (e.key === 'Escape' && qrGlassModal && !qrGlassModal.classList.contains('hidden')) {\n    closeQrModal();\n  }\n});\n\n// Auto-open modal if requested via URL (?pair or ?qr)\nif (window.location.search.includes('pair') || window.location.search.includes('qr')) {\n  setTimeout(openQrModal, 200);\n}\n\nglassThemeBtns.forEach(btn => {\n  btn.addEventListener('click', () => {\n    glassThemeBtns.forEach(b => b.classList.remove('active'));\n    btn.classList.add('active');\n    const theme = btn.dataset.theme;\n    activeModalTheme = theme;\n    if (kineticModalQr) {\n      kineticModalQr.setTheme(theme);\n    }\n    if (glassModalPanel) {\n      glassModalPanel.className = `glass-modal-panel theme-${theme}`;\n    }\n  });\n});\n\n// Auto-open if URL contains ?qr=open or ?qr=1 or hash is #qr\nif (window.location.search.includes('qr=') || window.location.hash === '#qr') {\n  openQrModal();\n}\n\nfunction handleIncomingMeshTransfer(transfer) {\n  // If sent by this device, ignore\n  if (transfer.fromSlot === mySlot) return;\n\n  // If targeted specifically to someone else, ignore\n  if (transfer.toSlot !== 'ALL' && transfer.toSlot !== mySlot) return;\n\n  if (incomingTransferCard) {\n    incomingFromText.textContent = `From Node [ ${transfer.fromSlot} ] -> [ ${transfer.toSlot} ]`;\n    incomingFileName.textContent = transfer.fileName;\n    incomingFileSize.textContent = formatBytes(transfer.fileSize);\n    incomingDownloadBtn.href = transfer.downloadUrl;\n    incomingDownloadBtn.setAttribute('download', transfer.fileName);\n    incomingTransferCard.classList.remove('hidden');\n\n    if (navigator.vibrate) navigator.vibrate([100, 50, 100]);\n  }\n}\n\nif (dismissIncomingBtn) {\n  dismissIncomingBtn.addEventListener('click', () => {\n    if (incomingTransferCard) incomingTransferCard.classList.add('hidden');\n  });\n}\n\nif (incomingDownloadBtn) {\n  incomingDownloadBtn.addEventListener('click', () => {\n    // Smooth auto-dismiss after download initiation\n    setTimeout(() => {\n      if (incomingTransferCard) incomingTransferCard.classList.add('hidden');\n    }, 2500);\n  });\n}\n\n// 5. Drag and Drop & Quick Action Pickers\nif (pickMediaBtn && mediaInput) {\n  pickMediaBtn.addEventListener('click', (e) => {\n    e.stopPropagation();\n    mediaInput.click();\n  });\n}\n\nif (pickFilesBtn && fileInput) {\n  pickFilesBtn.addEventListener('click', (e) => {\n    e.stopPropagation();\n    fileInput.click();\n  });\n}\n\nif (dropzone) {\n  dropzone.addEventListener('click', (e) => {\n    if (e.target && e.target.closest('#dropzoneQuickActions')) return;\n    if (dropzone.classList.contains('dropzone-busy')) return;\n    // On mobile devices, default to media gallery for fast video/photo selection\n    const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);\n    if (isMobile && mediaInput) {\n      mediaInput.click();\n    } else if (fileInput) {\n      fileInput.click();\n    }\n  });\n}\n\n['dragenter', 'dragover'].forEach(name => {\n  if (dropzone) {\n    dropzone.addEventListener(name, (e) => {\n      e.preventDefault();\n      dropzone.classList.add('dragover');\n      if (mascotFace) mascotFace.textContent = '{- o -}';\n    });\n  }\n});\n\n['dragleave', 'drop'].forEach(name => {\n  if (dropzone) {\n    dropzone.addEventListener(name, (e) => {\n      e.preventDefault();\n      dropzone.classList.remove('dragover');\n    });\n  }\n});\n\nif (dropzone) {\n  dropzone.addEventListener('drop', (e) => {\n    const files = e.dataTransfer.files;\n    if (files && files.length > 0) {\n      handleFiles(Array.from(files));\n    } else {\n      if (mascotFace) mascotFace.textContent = '{- _ -}';\n    }\n  });\n}\n\nif (fileInput) {\n  fileInput.addEventListener('change', () => {\n    if (fileInput.files && fileInput.files.length > 0) {\n      handleFiles(Array.from(fileInput.files));\n    }\n  });\n}\n\nif (mediaInput) {\n  mediaInput.addEventListener('change', () => {\n    if (mediaInput.files && mediaInput.files.length > 0) {\n      handleFiles(Array.from(mediaInput.files));\n    }\n  });\n}\n\nif (refreshFilesBtn) {\n  refreshFilesBtn.addEventListener('click', loadHostFiles);\n}\n\n// =========================================================\n// Triple-Layer Mobile Screen Stay-Awake (HTTP Compatible)\n// 1. navigator.wakeLock (HTTPS / Desktop)\n// 2. Invisible Canvas Stream Video Player (iOS Safari / Android)\n// 3. Silent WebAudio Oscillator (Background networking anchor)\n// =========================================================\nlet appWakeLock = null;\nlet wakeCanvasStream = null;\nlet wakeAudioCtx = null;\nlet wakeOsc = null;\n\nfunction startVideoWakeLock() {\n  try {\n    const video = document.getElementById('wakeLockVideo');\n    if (!video) return;\n    if (!wakeCanvasStream) {\n      const canvas = document.createElement('canvas');\n      canvas.width = 2;\n      canvas.height = 2;\n      const ctx = canvas.getContext('2d');\n      ctx.fillStyle = '#000000';\n      ctx.fillRect(0, 0, 2, 2);\n      if (canvas.captureStream) {\n        wakeCanvasStream = canvas.captureStream(1);\n      }\n    }\n    if (wakeCanvasStream && video.srcObject !== wakeCanvasStream) {\n      video.srcObject = wakeCanvasStream;\n    }\n    video.play().catch(() => {});\n  } catch (e) {}\n}\n\nfunction stopVideoWakeLock() {\n  try {\n    const video = document.getElementById('wakeLockVideo');\n    if (video) {\n      video.pause();\n      video.srcObject = null;\n    }\n  } catch (e) {}\n}\n\nfunction startAudioKeepAlive() {\n  try {\n    const AudioCtx = window.AudioContext || window.webkitAudioContext;\n    if (!AudioCtx) return;\n    if (!wakeAudioCtx) wakeAudioCtx = new AudioCtx();\n    if (wakeAudioCtx.state === 'suspended') {\n      wakeAudioCtx.resume().catch(() => {});\n    }\n    if (!wakeOsc) {\n      const osc = wakeAudioCtx.createOscillator();\n      const gain = wakeAudioCtx.createGain();\n      gain.gain.value = 0.00001; // inaudible\n      osc.connect(gain);\n      gain.connect(wakeAudioCtx.destination);\n      osc.start();\n      wakeOsc = osc;\n    }\n  } catch (e) {}\n}\n\nfunction stopAudioKeepAlive() {\n  try {\n    if (wakeOsc) {\n      wakeOsc.stop();\n      wakeOsc.disconnect();\n      wakeOsc = null;\n    }\n  } catch (e) {}\n}\n\nasync function requestScreenWakeLock() {\n  try {\n    if ('wakeLock' in navigator) {\n      appWakeLock = await navigator.wakeLock.request('screen');\n    }\n  } catch (e) {}\n  startVideoWakeLock();\n  startAudioKeepAlive();\n}\n\nfunction releaseScreenWakeLock() {\n  if (appWakeLock) {\n    appWakeLock.release().catch(() => {});\n    appWakeLock = null;\n  }\n  stopVideoWakeLock();\n  stopAudioKeepAlive();\n}\n\nfunction combineSignals(sigA, sigB) {\n  if (typeof AbortSignal.any === 'function') {\n    return AbortSignal.any([sigA, sigB].filter(Boolean));\n  }\n  const controller = new AbortController();\n  const onAbort = () => controller.abort();\n  if (sigA) {\n    if (sigA.aborted) return sigA;\n    sigA.addEventListener('abort', onAbort, { once: true });\n  }\n  if (sigB) {\n    if (sigB.aborted) return sigB;\n    sigB.addEventListener('abort', onAbort, { once: true });\n  }\n  return controller.signal;\n}\n\n// Bandwidth Smartness & Dynamic Allocation\n// Single-file mode: Allocates 100% of pipeline bandwidth to the single file (0 channel contention, direct full-speed stream)\n// Multi-file batch mode: Uses balanced 4MB chunks for responsive queue progression and individual resilience\nfunction getOptimalChunkConfig(fileSize, totalFiles = 1) {\n  if (totalFiles === 1) {\n    // Single file dedicated bandwidth allocation:\n    if (fileSize <= 64 * 1024 * 1024) {\n      // Files <= 64MB (e.g. 40MB video): 1 single continuous full-speed burst chunk!\n      return {\n        chunkSize: Math.max(1, fileSize),\n        concurrency: 1,\n        mode: 'Dedicated Full-Bandwidth Turbo Pipe'\n      };\n    }\n    if (fileSize <= 256 * 1024 * 1024) {\n      // 64MB - 256MB: 32MB chunks for maximum socket throughput without fragmentation\n      return {\n        chunkSize: 32 * 1024 * 1024,\n        concurrency: 1,\n        mode: 'High-Bandwidth Dedicated Pipe'\n      };\n    }\n    // Very large 4K single videos (> 256MB): 16MB chunks with dual-pipeline saturation\n    return {\n      chunkSize: 16 * 1024 * 1024,\n      concurrency: 2,\n      mode: 'Dual High-Speed Pipeline'\n    };\n  }\n\n  // Multi-File Batch Mode (totalFiles > 1):\n  if (fileSize > 350 * 1024 * 1024) {\n    return {\n      chunkSize: 8 * 1024 * 1024,\n      concurrency: 2,\n      mode: 'Multi-Item Batch Pipeline'\n    };\n  }\n  return {\n    chunkSize: 4 * 1024 * 1024,\n    concurrency: 2,\n    mode: 'Multi-Item Batch Pipeline'\n  };\n}\n\nfunction getOptimalChunkSize(fileSize, totalFiles = 1) {\n  return getOptimalChunkConfig(fileSize, totalFiles).chunkSize;\n}\n\n/**\n * Streams a binary chunk over XHR so single-file dedicated-pipe transfers emit\n * real-time upload progress and rely on an inactivity watchdog rather than a fixed timeout.\n */\nfunction uploadChunkViaXHR(url, blob, signal, onProgress, inactivityMs = 25000) {\n  return new Promise((resolve, reject) => {\n    if (signal && signal.aborted) {\n      const err = new Error('Transfer aborted');\n      err.name = 'AbortError';\n      reject(err);\n      return;\n    }\n\n    const xhr = new XMLHttpRequest();\n    let stalled = false;\n    let settled = false;\n    let lastLoaded = 0;\n    let stallTimer = null;\n\n    const cleanup = () => {\n      if (stallTimer) clearTimeout(stallTimer);\n      if (signal) signal.removeEventListener('abort', onSignalAbort);\n    };\n\n    const resetStallTimer = () => {\n      if (stallTimer) clearTimeout(stallTimer);\n      stallTimer = setTimeout(() => {\n        stalled = true;\n        xhr.abort();\n      }, inactivityMs);\n    };\n\n    const onSignalAbort = () => {\n      if (settled) return;\n      settled = true;\n      cleanup();\n      xhr.abort();\n      const err = new Error('Transfer aborted');\n      err.name = 'AbortError';\n      reject(err);\n    };\n\n    if (signal) {\n      signal.addEventListener('abort', onSignalAbort, { once: true });\n    }\n\n    xhr.open('PUT', url, true);\n    resetStallTimer();\n\n    xhr.upload.onprogress = (e) => {\n      if (settled) return;\n      if (e.loaded > lastLoaded) {\n        lastLoaded = e.loaded;\n        resetStallTimer();\n      }\n      if (e.lengthComputable && onProgress) {\n        onProgress(e.loaded);\n      }\n    };\n\n    xhr.onload = () => {\n      if (settled) return;\n      settled = true;\n      cleanup();\n      if (xhr.status >= 200 && xhr.status < 300) {\n        resolve();\n      } else {\n        reject(new Error(`Chunk upload failed with HTTP ${xhr.status}`));\n      }\n    };\n\n    xhr.onerror = () => {\n      if (settled) return;\n      settled = true;\n      cleanup();\n      reject(new Error('Network error during chunk upload'));\n    };\n\n    xhr.onabort = () => {\n      if (settled) return;\n      settled = true;\n      cleanup();\n      if (stalled) {\n        reject(new Error('Chunk upload stalled (inactivity timeout)'));\n      } else {\n        const err = new Error('Transfer aborted');\n        err.name = 'AbortError';\n        reject(err);\n      }\n    };\n\n    xhr.send(blob);\n  });\n}\n\n// Cancel Transfer Event Listener\nif (cancelTransferBtn) {\n  cancelTransferBtn.addEventListener('click', async () => {\n    isCurrentTransferCancelled = true;\n    isProcessingQueue = false;\n    const fileIdToCancel = currentUploadFileId;\n\n    if (currentUploadAbortController) {\n      try {\n        currentUploadAbortController.abort();\n      } catch (e) {}\n    }\n\n    currentUploadAbortController = null;\n    currentUploadFileId = null;\n\n    // Immediately purge queue and state so re-transfers start completely fresh\n    activeBatchQueue = [];\n    if (queueItemsList) queueItemsList.innerHTML = '';\n    if (batchSummaryBar) batchSummaryBar.classList.add('hidden');\n    if (queueListWrapper) queueListWrapper.classList.add('hidden');\n    if (fileInput) { fileInput.value = ''; fileInput.disabled = false; }\n    if (mediaInput) { mediaInput.value = ''; mediaInput.disabled = false; }\n    releaseScreenWakeLock();\n\n    transferStatus.textContent = 'Transfer cancelled.';\n    transferStatus.style.color = '#F87171';\n    transferSpeed.textContent = 'Cancelled';\n    transferEta.textContent = '--:--';\n    cancelTransferBtn.style.display = 'none';\n\n    if (fileIdToCancel) {\n      try {\n        await fetch(`/api/upload/cancel/${fileIdToCancel}`, { method: 'POST' });\n      } catch (e) {}\n    }\n\n    if (dropzone) {\n      dropzone.classList.remove('dropzone-busy');\n      if (dropzoneActionText) dropzoneActionText.textContent = 'Tap or Drag Files to Stream';\n    }\n\n    setTimeout(() => {\n      transferContainer.classList.add('hidden');\n      cancelTransferBtn.style.display = '';\n      transferStatus.style.color = '';\n      progressBar.style.width = '0%';\n    }, 1200);\n  });\n}\n\n// =========================================================\n// 6. Resilient Multi-Video Batch Queue Engine\n// =========================================================\nlet activeBatchQueue = [];\nlet isProcessingQueue = false;\n\nasync function handleFiles(newFiles) {\n  if (!newFiles || newFiles.length === 0) return;\n\n  // If previous queue is completed or stopped, ALWAYS clean the slate!\n  if (!isProcessingQueue) {\n    activeBatchQueue = [];\n    if (queueItemsList) queueItemsList.innerHTML = '';\n    if (batchSummaryBar) batchSummaryBar.classList.add('hidden');\n    if (queueListWrapper) queueListWrapper.classList.add('hidden');\n    if (retryFailedBtn) retryFailedBtn.classList.add('hidden');\n    progressBar.style.width = '0%';\n    if (batchProgressBar) batchProgressBar.style.width = '0%';\n  }\n\n  // Immediate UI feedback on selection\n  if (dropzoneActionText) {\n    dropzoneActionText.textContent = `Preparing ${newFiles.length} item${newFiles.length > 1 ? 's' : ''}...`;\n  }\n  if (dropzone) {\n    dropzone.classList.add('dropzone-busy');\n  }\n\n  // Request screen stay-awake immediately\n  await requestScreenWakeLock();\n\n  isCurrentTransferCancelled = false;\n\n  const startIndex = activeBatchQueue.length;\n  const itemsToAdd = newFiles.map((file, i) => ({\n    id: startIndex + i,\n    file,\n    name: file.name || `Video_${startIndex + i + 1}.mp4`,\n    size: file.size || 0,\n    status: 'waiting',\n    progress: 0,\n    uploadedBytes: 0\n  }));\n\n  activeBatchQueue.push(...itemsToAdd);\n\n  if (isProcessingQueue) {\n    renderQueueList();\n    updateBatchProgress();\n    return;\n  }\n\n  isProcessingQueue = true;\n  await processBatchQueue();\n}\n\nfunction renderQueueList() {\n  if (!queueItemsList) return;\n  queueItemsList.innerHTML = '';\n\n  activeBatchQueue.forEach(item => {\n    const el = document.createElement('div');\n    el.className = `queue-item ${item.status === 'uploading' ? 'active' : ''}`;\n\n    let statusText = 'Waiting';\n    let statusClass = 'waiting';\n    if (item.status === 'uploading') {\n      statusText = item.progress > 0 ? `${item.progress}%` : 'Sending';\n      statusClass = 'uploading';\n    } else if (item.status === 'done') {\n      statusText = 'Done';\n      statusClass = 'done';\n    } else if (item.status === 'failed') {\n      statusText = 'Failed';\n      statusClass = 'failed';\n    }\n\n    const safeItemName = escapeHtml(item.name);\n    el.innerHTML = `\n      <div class=\"queue-item-info\">\n        <span class=\"queue-item-name\" title=\"${safeItemName}\">${safeItemName}</span>\n        <span class=\"queue-item-size\">${formatBytes(item.size)}</span>\n      </div>\n      <span class=\"queue-status-pill ${statusClass}\" id=\"queuePill_${item.id}\">${statusText}</span>\n    `;\n    queueItemsList.appendChild(el);\n  });\n}\n\nfunction updateBatchProgress() {\n  if (!batchProgressBar || !batchCountBadge || !batchProgressStats) return;\n  const total = activeBatchQueue.length;\n  const completed = activeBatchQueue.filter(i => i.status === 'done').length;\n  const totalBytes = activeBatchQueue.reduce((acc, i) => acc + i.size, 0);\n  const uploadedBytes = activeBatchQueue.reduce((acc, i) => acc + (i.uploadedBytes || 0), 0);\n\n  batchCountBadge.textContent = `${completed} / ${total}`;\n  const pct = totalBytes > 0 ? Math.min(100, Math.round((uploadedBytes / totalBytes) * 100)) : 0;\n  batchProgressBar.style.width = `${pct}%`;\n  batchProgressStats.textContent = `${formatBytes(uploadedBytes)} / ${formatBytes(totalBytes)} (${pct}%)`;\n}\n\nasync function processBatchQueue() {\n  renderQueueList();\n  transferContainer.classList.remove('hidden');\n\n  const totalFiles = activeBatchQueue.length;\n  if (totalFiles > 1) {\n    if (batchSummaryBar) batchSummaryBar.classList.remove('hidden');\n    if (queueListWrapper) queueListWrapper.classList.remove('hidden');\n  }\n\n  updateBatchProgress();\n\n  let successCount = 0;\n  let failedCount = 0;\n\n  for (let idx = 0; idx < activeBatchQueue.length; idx++) {\n    if (isCurrentTransferCancelled) break;\n    const item = activeBatchQueue[idx];\n    if (item.status === 'done') {\n      successCount++;\n      continue;\n    }\n\n    item.status = 'uploading';\n    renderQueueList();\n\n    // Auto-scroll active item into view\n    const pill = document.getElementById(`queuePill_${item.id}`);\n    if (pill && pill.parentElement) {\n      pill.parentElement.scrollIntoView({ behavior: 'smooth', block: 'nearest' });\n    }\n\n    // Try uploading with up to 2 file-level retries\n    let ok = false;\n    for (let attempt = 1; attempt <= 2 && !ok && !isCurrentTransferCancelled; attempt++) {\n      if (attempt > 1) {\n        transferStatus.textContent = `Retrying item ${idx + 1} of ${totalFiles} (Attempt ${attempt}/2)... transfer will resume.`;\n        await new Promise(r => setTimeout(r, 1200));\n      }\n\n      ok = await uploadFileChunked(item.file, idx + 1, totalFiles, (bytes, size, pct) => {\n        item.uploadedBytes = bytes;\n        item.progress = pct;\n        updateBatchProgress();\n        const activePill = document.getElementById(`queuePill_${item.id}`);\n        if (activePill) activePill.textContent = `${pct}%`;\n      });\n    }\n\n    if (isCurrentTransferCancelled) break;\n\n    if (ok) {\n      item.status = 'done';\n      item.progress = 100;\n      item.uploadedBytes = item.size;\n      successCount++;\n    } else {\n      item.status = 'failed';\n      failedCount++;\n    }\n\n    renderQueueList();\n    updateBatchProgress();\n\n    // Micro-pause (120ms) to allow mobile garbage collection to sweep memory\n    await new Promise(r => setTimeout(r, 120));\n  }\n\n  isProcessingQueue = false;\n  releaseScreenWakeLock();\n\n  // Reset inputs\n  if (fileInput) { fileInput.value = ''; fileInput.disabled = false; }\n  if (mediaInput) { mediaInput.value = ''; mediaInput.disabled = false; }\n  if (dropzone) {\n    dropzone.classList.remove('dropzone-busy');\n    if (dropzoneActionText) dropzoneActionText.textContent = 'Tap or Drag Files to Stream';\n  }\n\n  if (!isCurrentTransferCancelled) {\n    if (failedCount > 0) {\n      transferStatus.textContent = `Queue completed: ${successCount} sent, ${failedCount} failed.`;\n      transferStatus.style.color = '#F87171';\n      if (retryFailedBtn) {\n        retryFailedBtn.classList.remove('hidden');\n        const text = document.getElementById('retryFailedBtnText');\n        if (text) text.textContent = `Retry ${failedCount} Failed`;\n      }\n    } else {\n      transferStatus.textContent = `All ${totalFiles} file${totalFiles > 1 ? 's' : ''} transferred successfully.`;\n      transferStatus.style.color = '#22C55E';\n      if (retryFailedBtn) retryFailedBtn.classList.add('hidden');\n\n      setTimeout(() => {\n        if (!isProcessingQueue) {\n          transferContainer.classList.add('hidden');\n          if (batchSummaryBar) batchSummaryBar.classList.add('hidden');\n          if (queueListWrapper) queueListWrapper.classList.add('hidden');\n          activeBatchQueue = [];\n          if (queueItemsList) queueItemsList.innerHTML = '';\n          transferStatus.style.color = '';\n        }\n      }, 3500);\n    }\n  }\n}\n\nif (retryFailedBtn) {\n  retryFailedBtn.addEventListener('click', async () => {\n    if (isProcessingQueue) return;\n    retryFailedBtn.classList.add('hidden');\n    activeBatchQueue.forEach(item => {\n      if (item.status === 'failed') {\n        item.status = 'waiting';\n        item.progress = 0;\n        item.uploadedBytes = 0;\n      }\n    });\n    isProcessingQueue = true;\n    await requestScreenWakeLock();\n    await processBatchQueue();\n  });\n}\n\n/**\n * Uploads a large file using tuned sparse chunk streaming & auto-resume.\n */\nasync function uploadFileChunked(file, queueIndex = 1, totalFiles = 1, onProgress = null) {\n  if (isCurrentTransferCancelled) return false;\n\n  const config = getOptimalChunkConfig(file.size, totalFiles);\n  const chunkSize = config.chunkSize;\n  const totalChunks = Math.max(1, Math.ceil(file.size / chunkSize));\n  const randTag = Math.random().toString(36).substring(2, 7);\n  const cleanBase = (file.name || 'video.mp4').replace(/[^a-zA-Z0-9._\\- ()]/g, '_');\n  const fileId = `${cleanBase}_${file.size}_${file.lastModified || Date.now()}_${randTag}`.replace(/[^a-zA-Z0-9_]/g, '_');\n\n  currentUploadAbortController = new AbortController();\n  currentUploadFileId = fileId;\n\n  transferContainer.classList.remove('hidden');\n  if (cancelTransferBtn) cancelTransferBtn.style.display = '';\n  transferFileName.textContent = totalFiles > 1 ? `[${queueIndex}/${totalFiles}] ${file.name || cleanBase}` : (file.name || cleanBase);\n  transferStats.textContent = `0 B / ${formatBytes(file.size)}`;\n  transferSpeed.textContent = 'Connecting...';\n  transferEta.textContent = '--:--';\n  progressBar.style.width = '0%';\n  transferChunks.textContent = totalFiles > 1 \n    ? `Queue ${queueIndex}/${totalFiles} • Chunk 0/${totalChunks}` \n    : (totalChunks === 1 ? 'Dedicated 100% Bandwidth Pipe' : `Dedicated Stream • Chunk 0/${totalChunks}`);\n\n  transferStatus.textContent = totalFiles > 1 \n    ? `Preparing item ${queueIndex} of ${totalFiles}...` \n    : (totalChunks === 1 ? 'Allocating 100% bandwidth to single file...' : 'Initializing dedicated stream...');\n\n  // Step 1: Initialize sparse session on host with 25s timeout\n  let initRes;\n  try {\n    const initCtrl = new AbortController();\n    const initTimer = setTimeout(() => initCtrl.abort(), 25000);\n    const combinedSignal = combineSignals(currentUploadAbortController.signal, initCtrl.signal);\n\n    initRes = await fetch('/api/upload/init', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      signal: combinedSignal,\n      body: JSON.stringify({\n        fileId,\n        fileName: file.name || cleanBase,\n        fileSize: file.size,\n        totalChunks,\n        chunkSize,\n        fromSlot: mySlot || 'Node',\n        queueIndex,\n        totalFiles\n      })\n    });\n    clearTimeout(initTimer);\n  } catch (e) {\n    if (isCurrentTransferCancelled) return false;\n  }\n\n  if (!initRes || !initRes.ok) {\n    if (isCurrentTransferCancelled) return false;\n    transferStatus.textContent = 'Failed to initialize session.';\n    return false;\n  }\n\n  // Step 2: Check existing status (auto-resume)\n  let receivedSet = new Set();\n  try {\n    const statusRes = await fetch(`/api/upload/status/${fileId}`, {\n      signal: currentUploadAbortController.signal\n    });\n    if (statusRes.ok) {\n      const statusData = await statusRes.json();\n      receivedSet = new Set(statusData.receivedChunks);\n    }\n  } catch (e) {}\n\n  let completedBytes = 0;\n  receivedSet.forEach((idx) => {\n    const cStart = idx * chunkSize;\n    const cEnd = Math.min(file.size, cStart + chunkSize);\n    completedBytes += (cEnd - cStart);\n  });\n\n  const inFlightBytes = new Map();\n  let startTime = Date.now();\n  let lastBytes = completedBytes;\n  let lastUiUpdate = 0;\n\n  function updateProgressUI(force = false) {\n    let activeTotal = 0;\n    inFlightBytes.forEach((val) => { activeTotal += val; });\n    const bytesUploaded = Math.min(file.size, completedBytes + activeTotal);\n\n    const now = Date.now();\n    if (!force && (now - lastUiUpdate < 120)) return;\n    lastUiUpdate = now;\n\n    const elapsedSec = (now - startTime) / 1000;\n    if (elapsedSec >= 0.45) {\n      const deltaBytes = bytesUploaded - lastBytes;\n      if (deltaBytes >= 0) {\n        const speedBps = deltaBytes / elapsedSec;\n        transferSpeed.textContent = `${(speedBps / (1024 * 1024)).toFixed(1)} MB/s`;\n\n        const remainingBytes = Math.max(0, file.size - bytesUploaded);\n        const etaSec = speedBps > 0 ? Math.ceil(remainingBytes / speedBps) : 0;\n        const etaMin = Math.floor(etaSec / 60);\n        const etaRemSec = etaSec % 60;\n        transferEta.textContent = `${etaMin}:${etaRemSec < 10 ? '0' : ''}${etaRemSec}`;\n      }\n      lastBytes = bytesUploaded;\n      startTime = now;\n    }\n\n    const percent = file.size > 0 ? Math.min(100, Math.round((bytesUploaded / file.size) * 100)) : 100;\n    progressBar.style.width = `${percent}%`;\n    transferStats.textContent = `${formatBytes(bytesUploaded)} / ${formatBytes(file.size)}`;\n    transferChunks.textContent = totalFiles > 1\n      ? `Queue ${queueIndex}/${totalFiles} • Chunk ${receivedSet.size}/${totalChunks}`\n      : (totalChunks === 1 ? '100% Dedicated Bandwidth' : `Dedicated Stream • Chunk ${receivedSet.size}/${totalChunks}`);\n\n    transferStatus.textContent = totalFiles > 1\n      ? `Streaming item ${queueIndex}/${totalFiles} (${formatBytes(chunkSize)} chunks)... active`\n      : (totalChunks === 1\n          ? `Streaming single file at full bandwidth (dedicated pipe)...`\n          : `Streaming dedicated pipe (${CONCURRENCY} channel${CONCURRENCY > 1 ? 's' : ''} active)...`);\n\n    if (onProgress) {\n      onProgress(bytesUploaded, file.size, percent);\n    }\n  }\n\n  // Step 3: Populate work queue with missing chunks\n  const chunkQueue = [];\n  for (let i = 0; i < totalChunks; i++) {\n    if (!receivedSet.has(i)) {\n      chunkQueue.push(i);\n    }\n  }\n\n  if (mascotFace) mascotFace.textContent = '{- U -}';\n\n  const CONCURRENCY = Math.min(config.concurrency, Math.max(1, chunkQueue.length));\n  let hasFailed = false;\n\n  async function worker() {\n    while (chunkQueue.length > 0 && !hasFailed && !isCurrentTransferCancelled) {\n      const i = chunkQueue.shift();\n      const start = i * chunkSize;\n      const end = Math.min(file.size, start + chunkSize);\n      const chunkLen = end - start;\n      const chunkBlob = file.slice(start, end);\n\n      let success = false;\n      let retries = 0;\n\n      while (!success && retries < 5 && !hasFailed && !isCurrentTransferCancelled) {\n        try {\n          inFlightBytes.set(i, 0);\n          await uploadChunkViaXHR(\n            `/api/upload/chunk/${fileId}/${i}`,\n            chunkBlob,\n            currentUploadAbortController ? currentUploadAbortController.signal : undefined,\n            (loaded) => {\n              inFlightBytes.set(i, Math.min(chunkLen, loaded));\n              updateProgressUI(false);\n            }\n          );\n\n          inFlightBytes.delete(i);\n          if (!receivedSet.has(i)) {\n            receivedSet.add(i);\n            completedBytes = Math.min(file.size, completedBytes + chunkLen);\n          }\n          success = true;\n          updateProgressUI(true);\n        } catch (err) {\n          inFlightBytes.delete(i);\n          if (isCurrentTransferCancelled || err.name === 'AbortError' || currentUploadAbortController?.signal?.aborted) {\n            hasFailed = true;\n            return;\n          }\n          retries++;\n          transferStatus.textContent = `Retrying chunk ${i + 1} (Attempt ${retries}/5)...`;\n          await new Promise(r => setTimeout(r, 400 * retries));\n        }\n      }\n\n      if (!success) {\n        hasFailed = true;\n        if (!isCurrentTransferCancelled) {\n          transferStatus.textContent = `Interrupted on chunk ${i + 1}. Auto-resuming...`;\n        }\n        return;\n      }\n    }\n  }\n\n  const workers = Array.from({ length: CONCURRENCY }, () => worker());\n  await Promise.all(workers);\n\n  if (hasFailed || isCurrentTransferCancelled) {\n    currentUploadAbortController = null;\n    currentUploadFileId = null;\n    return false;\n  }\n\n  // Step 4: Finalize file on host + Mesh routing\n  transferStatus.textContent = totalFiles > 1 ? `Finalizing item ${queueIndex} of ${totalFiles}...` : 'Finalizing transfer & routing...';\n  try {\n    const finalRes = await fetch(`/api/upload/complete/${fileId}`, {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      signal: currentUploadAbortController ? currentUploadAbortController.signal : undefined,\n      body: JSON.stringify({\n        fromSlot: mySlot || 'Node',\n        toSlot: targetSlot,\n        queueIndex,\n        totalFiles\n      })\n    });\n\n    if (finalRes.ok) {\n      if (mascotFace) mascotFace.textContent = '{- ^ -}';\n      progressBar.style.width = '100%';\n      transferSpeed.textContent = 'Done!';\n      transferEta.textContent = '0:00';\n\n      if (targetSlot === 'U') {\n        transferStatus.textContent = totalFiles > 1 ? `Transferred item ${queueIndex} of ${totalFiles}.` : 'Transferred to Host Downloads/uDrop.';\n      } else if (targetSlot === 'ALL') {\n        transferStatus.textContent = 'Broadcasted to All Devices in UXIOM Mesh.';\n      } else {\n        transferStatus.textContent = `Beamed to Node [ ${targetSlot} ] via Host Bridge.`;\n      }\n      transferStatus.style.color = '#22C55E';\n\n      currentUploadAbortController = null;\n      currentUploadFileId = null;\n      return true;\n    } else {\n      transferStatus.textContent = 'Error during finalization.';\n      currentUploadAbortController = null;\n      currentUploadFileId = null;\n      return false;\n    }\n  } catch (err) {\n    if (isCurrentTransferCancelled) return false;\n    transferStatus.textContent = 'Host failed to finalize file.';\n    currentUploadAbortController = null;\n    currentUploadFileId = null;\n    return false;\n  }\n}\n\n// 7. Initial Run & Intervals\ncheckHostConnection();\nloadHostFiles();\njoinMesh();\nconnectMeshEvents();\n\nsetInterval(checkHostConnection, 6000);\nsetInterval(loadHostFiles, 8000);\n\n// Keep-alive heartbeat every 15s\nsetInterval(async () => {\n  if (myClientId) {\n    try {\n      await fetch('/api/mesh/heartbeat', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ clientId: myClientId })\n      });\n    } catch (e) {}\n  }\n}, 15000);\n\n// Notify mesh when tab/browser closes to free slot immediately\nwindow.addEventListener('beforeunload', () => {\n  if (myClientId && navigator.sendBeacon) {\n    const payload = new Blob([JSON.stringify({ clientId: myClientId })], { type: 'application/json' });\n    navigator.sendBeacon('/api/mesh/leave', payload);\n  }\n});\n",
  "qr-kinetic.js": "(function (global) {\n  const THEMES = {\n    obsidian: {\n      cardBgTop: '#1A1C23',\n      cardBgBot: '#09090D',\n      cardFg: '#FAFAFA',\n      qrBgTop: '#161820',\n      qrBgBot: '#0B0C10',\n      qrFg: '#FAFAFA',\n      qrGlow: 'rgba(255, 255, 255, 0.24)',\n      sub: '#A1A1AA',\n      rimHi: 'rgba(255, 255, 255, 0.55)',\n      rimMid: 'rgba(180, 190, 210, 0.14)',\n      sheenStart: 'rgba(255, 255, 255, 0.14)',\n      flare: true\n    },\n    titanium: {\n      cardBgTop: '#2E2E36',\n      cardBgBot: '#1B1B20',\n      cardFg: '#FAFAFA',\n      qrBgTop: '#FAFAFA',\n      qrBgBot: '#EFEFF2',\n      qrFg: '#09090B',\n      qrGlow: 'rgba(0, 0, 0, 0)',\n      sub: '#D4D4D8',\n      rimHi: 'rgba(255, 255, 255, 0.42)',\n      rimMid: 'rgba(255, 255, 255, 0.12)',\n      sheenStart: 'rgba(255, 255, 255, 0.11)',\n      flare: true\n    },\n    paper: {\n      cardBgTop: '#FFFFFF',\n      cardBgBot: '#F2F2F5',\n      cardFg: '#09090B',\n      qrBgTop: '#0B0C10',\n      qrBgBot: '#09090B',\n      qrFg: '#FAFAFA',\n      qrGlow: 'rgba(255, 255, 255, 0.2)',\n      sub: '#52525B',\n      rimHi: 'rgba(9, 9, 11, 0.22)',\n      rimMid: 'rgba(9, 9, 11, 0.08)',\n      sheenStart: 'rgba(255, 255, 255, 0.35)',\n      flare: false\n    }\n  };\n\n  function hashFloat(r, c, salt) {\n    let x = Math.sin((r + 1) * 12.9898 + (c + 1) * 78.233 + salt * 43.123) * 43758.5453;\n    return x - Math.floor(x);\n  }\n\n  function easeOutCubic(x) {\n    return 1 - Math.pow(1 - x, 3);\n  }\n\n  function easeInCubic(x) {\n    return x * x * x;\n  }\n\n  function createKineticQr(canvas, options) {\n    const opts = options || {};\n    let currentTheme = opts.theme || 'obsidian';\n    let currentMode = opts.mode || 'mdns';\n    let particles = [];\n    let qrSize = 0;\n    let connectLabel = 'Connecting...';\n    let progress = 0; // 0 = dismantled/scattered, 1 = crisp assembled\n    let animDir = 0;  // +1 assembling, -1 dismantling, 0 idle\n    let animStart = 0;\n    let animDur = 480;\n    let rafId = null;\n    let statusBanner = '';\n    let onDismantleDone = null;\n\n    function buildParticles(rows, size) {\n      qrSize = size;\n      particles = [];\n      const half = (size - 1) / 2;\n      const maxDist = Math.sqrt(half * half * 2) || 1;\n\n      for (let r = 0; r < size; r++) {\n        const row = rows[r] || '';\n        for (let c = 0; c < size; c++) {\n          if (row[c] !== '1') continue;\n          const dx = c - half;\n          const dy = r - half;\n          const distNorm = Math.sqrt(dx * dx + dy * dy) / maxDist;\n          const baseAngle = Math.atan2(dy, dx);\n          const swirl = (hashFloat(r, c, 1) - 0.5) * 1.35 + (dx === 0 && dy === 0 ? 0.5 : 0);\n          const radialBoost = 0.55 + hashFloat(r, c, 2) * 0.95;\n\n          const isFinder =\n            (r < 7 && c < 7) ||\n            (r < 7 && c >= size - 7) ||\n            (r >= size - 7 && c < 7);\n\n          particles.push({\n            r,\n            c,\n            angle: baseAngle + swirl,\n            radialBoost,\n            stagger: isFinder ? distNorm * 0.14 : distNorm * 0.28,\n            isFinder\n          });\n        }\n      }\n    }\n\n    function drawRoundedRect(ctx, x, y, w, h, radius) {\n      const r = Math.min(radius, w / 2, h / 2);\n      ctx.beginPath();\n      ctx.moveTo(x + r, y);\n      ctx.arcTo(x + w, y, x + w, y + h, r);\n      ctx.arcTo(x + w, y + h, x, y + h, r);\n      ctx.arcTo(x, y + h, x, y, r);\n      ctx.arcTo(x, y, x + w, y, r);\n      ctx.closePath();\n    }\n\n    function renderFrame(t) {\n      if (!canvas) return;\n      const dpr = window.devicePixelRatio || 1;\n      const cssW = canvas.clientWidth || 320;\n      const cssH = canvas.clientHeight || 420;\n      if (canvas.width !== Math.round(cssW * dpr) || canvas.height !== Math.round(cssH * dpr)) {\n        canvas.width = Math.round(cssW * dpr);\n        canvas.height = Math.round(cssH * dpr);\n      }\n\n      const ctx = canvas.getContext('2d');\n      ctx.save();\n      ctx.scale(dpr, dpr);\n\n      const theme = THEMES[currentTheme] || THEMES.obsidian;\n      ctx.clearRect(0, 0, cssW, cssH);\n\n      function drawSpecularFlare(fx, fy, rx) {\n        const g = ctx.createRadialGradient(fx, fy, 0, fx, fy, rx);\n        g.addColorStop(0, 'rgba(255, 255, 255, 0.72)');\n        g.addColorStop(0.45, 'rgba(255, 255, 255, 0.18)');\n        g.addColorStop(1, 'rgba(255, 255, 255, 0)');\n        ctx.save();\n        ctx.translate(fx, fy);\n        ctx.scale(1, 0.28);\n        ctx.fillStyle = g;\n        ctx.beginPath();\n        ctx.arc(0, 0, rx, 0, Math.PI * 2);\n        ctx.fill();\n        ctx.restore();\n      }\n\n      // Outer Frosted Glass Card Surface\n      drawRoundedRect(ctx, 1, 1, cssW - 2, cssH - 2, 22);\n      const outerFill = ctx.createLinearGradient(0, 0, cssW, cssH);\n      outerFill.addColorStop(0, theme.cardBgTop);\n      outerFill.addColorStop(1, theme.cardBgBot);\n      ctx.fillStyle = outerFill;\n      ctx.fill();\n\n      const outerRim = ctx.createLinearGradient(0, 0, cssW, cssH);\n      outerRim.addColorStop(0, theme.rimHi);\n      outerRim.addColorStop(0.5, theme.rimMid);\n      outerRim.addColorStop(1, theme.rimHi);\n      ctx.strokeStyle = outerRim;\n      ctx.lineWidth = 1.4;\n      ctx.stroke();\n\n      // Header Branding\n      ctx.fillStyle = theme.sub;\n      ctx.font = '700 10px ui-sans-serif, system-ui, -apple-system, sans-serif';\n      ctx.textBaseline = 'top';\n      ctx.fillText('UXIOM MESH  •  4K ZERO-ROUTER P2P', 22, 20);\n\n      ctx.fillStyle = theme.cardFg;\n      ctx.font = '800 22px ui-sans-serif, system-ui, -apple-system, sans-serif';\n      ctx.fillText('uDrop', 22, 36);\n\n      // Liquid Glass QR Well\n      const qrBoxPad = 24;\n      const qrBoxSize = Math.min(cssW - qrBoxPad * 2, cssH - 140);\n      const qrBoxX = (cssW - qrBoxSize) / 2;\n      const qrBoxY = 78;\n\n      ctx.save();\n      drawRoundedRect(ctx, qrBoxX, qrBoxY, qrBoxSize, qrBoxSize, 20);\n      const qrFill = ctx.createLinearGradient(qrBoxX, qrBoxY, qrBoxX + qrBoxSize, qrBoxY + qrBoxSize);\n      qrFill.addColorStop(0, theme.qrBgTop);\n      qrFill.addColorStop(1, theme.qrBgBot);\n      ctx.fillStyle = qrFill;\n      ctx.globalAlpha = animDir === -1 ? Math.max(0.08, t) : Math.min(1, 0.25 + t * 0.75);\n      ctx.fill();\n      ctx.clip();\n\n      // 32-deg diagonal glass light reflection across top-left face\n      const sheenGrad = ctx.createLinearGradient(qrBoxX, qrBoxY, qrBoxX + qrBoxSize * 0.65, qrBoxY + qrBoxSize * 0.85);\n      sheenGrad.addColorStop(0, theme.sheenStart);\n      sheenGrad.addColorStop(1, 'rgba(255, 255, 255, 0)');\n      ctx.fillStyle = sheenGrad;\n      ctx.beginPath();\n      ctx.moveTo(qrBoxX, qrBoxY);\n      ctx.lineTo(qrBoxX + qrBoxSize * 0.42, qrBoxY);\n      ctx.lineTo(qrBoxX + qrBoxSize * 0.72, qrBoxY + qrBoxSize);\n      ctx.lineTo(qrBoxX + qrBoxSize * 0.14, qrBoxY + qrBoxSize);\n      ctx.closePath();\n      ctx.fill();\n\n      const cx = qrBoxX + qrBoxSize / 2;\n      const cy = qrBoxY + qrBoxSize / 2;\n\n      if (qrSize > 0 && particles.length > 0) {\n        const quiet = 18;\n        const inner = qrBoxSize - quiet * 2;\n        const cell = inner / qrSize;\n        const maxScatter = qrBoxSize * 0.52;\n\n        ctx.fillStyle = theme.qrFg;\n        ctx.shadowColor = theme.qrGlow;\n        ctx.shadowBlur = 8;\n        for (let i = 0; i < particles.length; i++) {\n          const p = particles[i];\n          const localRaw = Math.max(0, Math.min(1, (t - p.stagger) / (1 - 0.28)));\n          const eased = animDir === -1 ? easeInCubic(localRaw) : easeOutCubic(localRaw);\n\n          const tx = qrBoxX + quiet + p.c * cell;\n          const ty = qrBoxY + quiet + p.r * cell;\n          const scatterDist = (1 - eased) * maxScatter * p.radialBoost;\n          const px = tx + Math.cos(p.angle) * scatterDist;\n          const py = ty + Math.sin(p.angle) * scatterDist;\n          const scale = 0.28 + 0.72 * eased;\n          const alpha = Math.max(0, Math.min(1, eased * 1.15));\n\n          ctx.globalAlpha = alpha;\n          const drawW = Math.ceil(cell * scale);\n          const ox = px + (cell - drawW) * 0.5;\n          const oy = py + (cell - drawW) * 0.5;\n          ctx.fillRect(ox, oy, drawW, drawW);\n        }\n        ctx.shadowBlur = 0;\n      }\n\n      if (statusBanner && t <= 0.25) {\n        const badgeAlpha = Math.min(1, (0.25 - t) / 0.25);\n        ctx.globalAlpha = badgeAlpha;\n        ctx.fillStyle = theme.cardFg;\n        ctx.font = '700 13px ui-sans-serif, system-ui, -apple-system, sans-serif';\n        ctx.textAlign = 'center';\n        ctx.textBaseline = 'middle';\n        ctx.fillText(statusBanner, cx, cy);\n        ctx.textAlign = 'left';\n      }\n\n      ctx.restore();\n\n      // Chrome Rim + Specular Edge Glints on QR Well\n      drawRoundedRect(ctx, qrBoxX, qrBoxY, qrBoxSize, qrBoxSize, 20);\n      ctx.strokeStyle = outerRim;\n      ctx.lineWidth = 1.4;\n      ctx.stroke();\n\n      if (theme.flare) {\n        drawSpecularFlare(qrBoxX + qrBoxSize * 0.74, qrBoxY, 34);\n        drawSpecularFlare(qrBoxX + qrBoxSize * 0.24, qrBoxY + qrBoxSize, 34);\n      }\n\n      // Footer Address & Status\n      ctx.fillStyle = theme.sub;\n      ctx.font = '600 11px ui-monospace, SFMono-Regular, Menlo, monospace';\n      ctx.textBaseline = 'bottom';\n      ctx.fillText(connectLabel, 22, cssH - 22);\n\n      ctx.restore();\n    }\n\n    function step(now) {\n      if (!animDir) return;\n      const elapsed = now - animStart;\n      const frac = Math.min(1, elapsed / animDur);\n      progress = animDir === 1 ? frac : (1 - frac);\n      renderFrame(progress);\n\n      if (frac < 1) {\n        rafId = requestAnimationFrame(step);\n      } else {\n        const finishedDir = animDir;\n        animDir = 0;\n        rafId = null;\n        progress = finishedDir === 1 ? 1 : 0;\n        renderFrame(progress);\n        if (finishedDir === -1 && typeof onDismantleDone === 'function') {\n          const cb = onDismantleDone;\n          onDismantleDone = null;\n          cb();\n        }\n      }\n    }\n\n    function startAnim(dir, dur, doneCb) {\n      if (rafId) cancelAnimationFrame(rafId);\n      animDir = dir;\n      animDur = dur || (dir === 1 ? 480 : 520);\n      animStart = performance.now();\n      onDismantleDone = doneCb || null;\n      rafId = requestAnimationFrame(step);\n    }\n\n    async function loadMatrix(mode) {\n      if (mode) currentMode = mode;\n      const res = await fetch(`/api/qr.matrix?mode=${encodeURIComponent(currentMode)}&t=${Date.now()}`);\n      if (!res.ok) return;\n      const data = await res.json();\n      connectLabel = data.connectUrl || data.maskedLabel || '';\n      buildParticles(data.rows || [], data.size || 0);\n    }\n\n    return {\n      async assemble(optionsArg) {\n        const o = optionsArg || {};\n        if (o.theme) currentTheme = o.theme;\n        if (o.mode) currentMode = o.mode;\n        statusBanner = '';\n        await loadMatrix(currentMode);\n        progress = 0;\n        startAnim(1, o.duration || 480);\n      },\n      async setTheme(theme) {\n        currentTheme = theme || 'obsidian';\n        if (particles.length === 0) {\n          await loadMatrix(currentMode);\n        }\n        progress = 0;\n        startAnim(1, 380);\n      },\n      disassemble(bannerText, doneCb) {\n        statusBanner = bannerText || 'Paired Device Connected';\n        if (particles.length === 0) {\n          if (doneCb) doneCb();\n          return;\n        }\n        startAnim(-1, 520, doneCb);\n      },\n      redraw() {\n        renderFrame(progress);\n      }\n    };\n  }\n\n  global.createKineticQr = createKineticQr;\n})(window);\n",
  "qr.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n  <title>uDrop — Optical Pairing Card</title>\n  <link rel=\"icon\" type=\"image/svg+xml\" href=\"assets/icon-brand.svg\">\n  <link rel=\"stylesheet\" href=\"style.css\">\n  <style>\n    body {\n      background: #09090b;\n      min-height: 100vh;\n      display: flex;\n      flex-direction: column;\n      justify-content: center;\n      align-items: center;\n      padding: 24px;\n      margin: 0;\n      font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\n    }\n\n    .qr-showcase {\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      gap: 20px;\n      max-width: 400px;\n      width: 100%;\n    }\n\n    .card-wrapper {\n      width: 100%;\n      border-radius: 28px;\n      overflow: hidden;\n      box-shadow: 0 25px 60px rgba(0, 0, 0, 0.8), 0 0 1px 1px rgba(255, 255, 255, 0.12);\n      animation: floatCard 0.5s cubic-bezier(0.16, 1, 0.3, 1);\n      transition: transform 0.3s ease, box-shadow 0.3s ease;\n    }\n\n    .card-wrapper:hover {\n      transform: translateY(-4px);\n      box-shadow: 0 30px 70px rgba(0, 0, 0, 0.9), 0 0 1px 1px rgba(255, 255, 255, 0.20);\n    }\n\n    @keyframes floatCard {\n      from { opacity: 0; transform: translateY(16px) scale(0.96); }\n      to { opacity: 1; transform: translateY(0) scale(1); }\n    }\n\n    #qrSvgImage {\n      display: block;\n      width: 100%;\n      height: auto;\n    }\n\n    .theme-picker {\n      display: flex;\n      align-items: center;\n      gap: 8px;\n      background: rgba(255, 255, 255, 0.05);\n      backdrop-filter: blur(12px);\n      border: 1px solid rgba(255, 255, 255, 0.1);\n      padding: 6px 10px;\n      border-radius: 100px;\n    }\n\n    .theme-btn {\n      background: transparent;\n      border: none;\n      color: #9ca3af;\n      font-size: 12px;\n      font-weight: 700;\n      padding: 6px 14px;\n      border-radius: 100px;\n      cursor: pointer;\n      transition: all 0.2s;\n    }\n\n    .theme-btn:hover {\n      color: #fff;\n    }\n\n    .theme-btn.active {\n      background: rgba(255, 255, 255, 0.15);\n      color: #fff;\n    }\n\n    .footer-actions {\n      display: flex;\n      gap: 12px;\n      width: 100%;\n    }\n\n    .btn-action {\n      flex: 1;\n      text-align: center;\n      padding: 12px;\n      font-size: 13px;\n      font-weight: 800;\n      border-radius: 14px;\n      text-decoration: none;\n      transition: all 0.2s;\n    }\n\n    .btn-action-primary {\n      background: #fff;\n      color: #000;\n    }\n\n    .btn-action-primary:hover {\n      background: #e5e7eb;\n    }\n\n    .btn-action-secondary {\n      background: rgba(255, 255, 255, 0.06);\n      color: #e5e7eb;\n      border: 1px solid rgba(255, 255, 255, 0.12);\n    }\n\n    .btn-action-secondary:hover {\n      background: rgba(255, 255, 255, 0.12);\n    }\n  </style>\n</head>\n<body>\n  <div class=\"qr-showcase\">\n    <!-- Theme Switcher -->\n    <div class=\"theme-picker\">\n      <button class=\"theme-btn active\" data-theme=\"obsidian\">Obsidian</button>\n      <button class=\"theme-btn\" data-theme=\"titanium\">Titanium</button>\n      <button class=\"theme-btn\" data-theme=\"paper\">Inverted White</button>\n    </div>\n\n    <!-- Sleek Kinetic QR Card -->\n    <div class=\"card-wrapper\" id=\"cardWrapper\">\n      <canvas id=\"qrShowcaseCanvas\" style=\"display: block; width: 100%; height: 470px;\" aria-label=\"uDrop Custom Sleek QR Card\"></canvas>\n    </div>\n\n    <!-- Actions -->\n    <div class=\"footer-actions\">\n      <a href=\"/\" class=\"btn-action btn-action-primary\">Open Dashboard</a>\n      <a id=\"downloadSvgBtn\" href=\"/api/qr.svg?theme=obsidian\" download=\"udrop-qr.svg\" class=\"btn-action btn-action-secondary\">Save Vector SVG</a>\n    </div>\n  </div>\n\n  <script src=\"qr-kinetic.js\"></script>\n  <script>\n    const canvas = document.getElementById('qrShowcaseCanvas');\n    const downloadBtn = document.getElementById('downloadSvgBtn');\n    const cardWrapper = document.getElementById('cardWrapper');\n    const themeButtons = document.querySelectorAll('.theme-btn');\n    const kinetic = window.createKineticQr(canvas, { theme: 'obsidian' });\n    let initialMobileCount = null;\n    let paired = false;\n\n    kinetic.assemble({ theme: 'obsidian' });\n\n    themeButtons.forEach(btn => {\n      btn.addEventListener('click', () => {\n        themeButtons.forEach(b => b.classList.remove('active'));\n        btn.classList.add('active');\n        const theme = btn.dataset.theme;\n        downloadBtn.href = `/api/qr.svg?theme=${theme}`;\n        kinetic.setTheme(theme);\n\n        if (theme === 'paper') {\n          cardWrapper.style.boxShadow = '0 25px 60px rgba(0, 0, 0, 0.5), 0 0 1px 1px rgba(255, 255, 255, 0.4)';\n        } else if (theme === 'titanium') {\n          cardWrapper.style.boxShadow = '0 25px 60px rgba(0, 0, 0, 0.7), 0 0 35px rgba(255, 255, 255, 0.08)';\n        } else {\n          cardWrapper.style.boxShadow = '0 25px 60px rgba(0, 0, 0, 0.9), 0 0 1px 1px rgba(255, 255, 255, 0.12)';\n        }\n      });\n    });\n\n    const es = new EventSource('/api/mesh/events');\n    es.onmessage = (e) => {\n      try {\n        const msg = JSON.parse(e.data);\n        if (msg.type === 'ring_update' && Array.isArray(msg.ring)) {\n          const count = msg.ring.filter(n => n.assigned && !n.isHost).length;\n          if (initialMobileCount === null) {\n            initialMobileCount = count;\n            return;\n          }\n          if (!paired && count > initialMobileCount) {\n            paired = true;\n            kinetic.disassemble('Device Connected', () => {\n              setTimeout(() => { window.location.href = '/'; }, 400);\n            });\n          }\n        } else if (msg.type === 'qr_scanned' && !paired) {\n          paired = true;\n          kinetic.disassemble('Pairing Phone...', () => {\n            setTimeout(() => { window.location.href = '/'; }, 500);\n          });\n        }\n      } catch {}\n    };\n  </script>\n</body>\n</html>\n",
  "island.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>uDrop • Dynamic Island HUD</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&family=JetBrains+Mono:wght@500;700;800&display=swap\" rel=\"stylesheet\">\n  <link rel=\"stylesheet\" href=\"style.css\">\n  <style>\n    body {\n      background: rgba(10, 11, 16, 0.95);\n      margin: 0;\n      padding: 0;\n      min-height: 100vh;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      justify-content: flex-start;\n      overflow: hidden;\n      font-family: 'Inter', system-ui, -apple-system, sans-serif;\n    }\n    .hud-backdrop {\n      width: 100%;\n      height: 100vh;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      padding-top: 24px;\n    }\n    .hud-hint {\n      margin-top: 130px;\n      font-size: 11px;\n      color: rgba(255, 255, 255, 0.4);\n      letter-spacing: 0.3px;\n      text-align: center;\n      font-family: ui-monospace, monospace;\n    }\n    .hud-hint a {\n      color: var(--accent-cyan);\n      text-decoration: none;\n    }\n    .hud-hint a:hover {\n      text-decoration: underline;\n    }\n  </style>\n</head>\n<body>\n  <div class=\"hud-backdrop\">\n    <!-- Liquid Glass Dynamic Island Overlay -->\n    <div id=\"dynamicIsland\" class=\"dynamic-island state-idle\" title=\"Click to open uDrop folder\">\n      <div class=\"island-content\">\n        <!-- State 1: Idle -->\n        <div class=\"island-idle\">\n          <span class=\"island-pulse\"></span>\n          <span class=\"island-idle-text\">uDrop Mesh Active</span>\n          <span class=\"island-badge\">[ U ]</span>\n        </div>\n\n        <!-- State 2: Active Receiving -->\n        <div class=\"island-receiving\">\n          <div class=\"island-left\">\n            <div class=\"island-wave\">\n              <span></span><span></span><span></span><span></span>\n            </div>\n          </div>\n          <div class=\"island-center\">\n            <div class=\"island-title-row\">\n              <span class=\"island-source\">Receiving from <b id=\"islandFromNode\">[ X ]</b></span>\n              <span id=\"islandSpeed\" class=\"island-speed\">-- MB/s</span>\n            </div>\n            <div class=\"island-filename\" id=\"islandFileName\">filename.ext</div>\n            <div class=\"island-progress-track\">\n              <div id=\"islandProgressBar\" class=\"island-progress-fill\" style=\"width: 0%\"></div>\n            </div>\n          </div>\n          <div class=\"island-right\">\n            <span id=\"islandPercent\" class=\"island-percent\">0%</span>\n          </div>\n        </div>\n\n        <!-- State 3: Complete & Hero Action -->\n        <div class=\"island-complete\">\n          <div class=\"island-complete-left\">\n            <span class=\"island-check\">\n              <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\"><polyline points=\"20 6 9 17 4 12\"></polyline></svg>\n            </span>\n          </div>\n          <div class=\"island-complete-center\">\n            <div class=\"island-complete-title\">File Received</div>\n            <div class=\"island-complete-meta\">\n              <span id=\"islandCompleteName\">photo.jpg</span>\n              <span class=\"island-dot\">•</span>\n              <span id=\"islandCompleteSize\">26 KB</span>\n            </div>\n          </div>\n          <div class=\"island-complete-right\">\n            <button id=\"islandOpenFolderBtn\" class=\"btn-island-action\" title=\"Show in Windows File Explorer\">\n              <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z\"></path></svg>\n              <span>Show in Explorer</span>\n            </button>\n            <button id=\"islandDismissBtn\" class=\"btn-island-close\" title=\"Dismiss\">\n              <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"></line><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"></line></svg>\n            </button>\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"hud-hint\">\n      Liquid Glass Dynamic Island Overlay HUD • <a href=\"/\">Open Full Dashboard</a>\n    </div>\n  </div>\n\n  <script>\n    function formatBytes(bytes) {\n      if (!bytes || bytes === 0) return '0 B';\n      const k = 1024;\n      const sizes = ['B', 'KB', 'MB', 'GB', 'TB'];\n      const i = Math.floor(Math.log(bytes) / Math.log(k));\n      return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];\n    }\n\n    const dynamicIsland = document.getElementById('dynamicIsland');\n    const islandFromNode = document.getElementById('islandFromNode');\n    const islandSpeed = document.getElementById('islandSpeed');\n    const islandFileName = document.getElementById('islandFileName');\n    const islandProgressBar = document.getElementById('islandProgressBar');\n    const islandPercent = document.getElementById('islandPercent');\n    const islandCompleteName = document.getElementById('islandCompleteName');\n    const islandCompleteSize = document.getElementById('islandCompleteSize');\n    const islandOpenFolderBtn = document.getElementById('islandOpenFolderBtn');\n    const islandDismissBtn = document.getElementById('islandDismissBtn');\n\n    let islandRevertTimer = null;\n    let currentHostTransfer = null;\n    let lastReceivedFile = null;\n    let islandAudioCtx = null;\n\n    function setIslandState(state) {\n      if (!dynamicIsland) return;\n      dynamicIsland.classList.remove('state-idle', 'state-receiving', 'state-complete');\n      dynamicIsland.classList.add(state);\n    }\n\n    function playSuccessChime() {\n      try {\n        const AudioCtx = window.AudioContext || window.webkitAudioContext;\n        if (!AudioCtx) return;\n        if (!islandAudioCtx) islandAudioCtx = new AudioCtx();\n        if (islandAudioCtx.state === 'suspended') {\n          islandAudioCtx.resume();\n        }\n        const now = islandAudioCtx.currentTime;\n\n        const playTone = (freq, start, duration, gainVal = 0.16) => {\n          const osc = islandAudioCtx.createOscillator();\n          const gain = islandAudioCtx.createGain();\n          osc.type = 'sine';\n          osc.frequency.setValueAtTime(freq, start);\n          gain.gain.setValueAtTime(0.001, start);\n          gain.gain.linearRampToValueAtTime(gainVal, start + 0.02);\n          gain.gain.exponentialRampToValueAtTime(0.0001, start + duration);\n          osc.connect(gain);\n          gain.connect(islandAudioCtx.destination);\n          osc.start(start);\n          osc.stop(start + duration);\n        };\n\n        playTone(659.25, now, 0.22, 0.15);\n        playTone(1046.50, now + 0.10, 0.40, 0.20);\n      } catch (err) {}\n    }\n\n    const eventSource = new EventSource('/api/mesh/events');\n\n    eventSource.onmessage = (e) => {\n      try {\n        const data = JSON.parse(e.data);\n        if (data.type === 'host_transfer_start') {\n          if (islandRevertTimer) clearTimeout(islandRevertTimer);\n          currentHostTransfer = {\n            fileId: data.fileId,\n            fileName: data.fileName,\n            fileSize: data.fileSize || 0,\n            totalChunks: data.totalChunks || 1,\n            fromSlot: data.fromSlot || 'Node',\n            queueIndex: data.queueIndex || 1,\n            totalFiles: data.totalFiles || 1,\n            startTime: Date.now(),\n            lastBytes: 0,\n            lastTime: Date.now()\n          };\n          if (data.totalFiles && data.totalFiles > 1) {\n            if (islandFileName) islandFileName.textContent = `[${data.queueIndex}/${data.totalFiles}] ${data.fileName}`;\n            if (islandFromNode) islandFromNode.textContent = `[ ${data.fromSlot || 'Node'} ] Queue ${data.queueIndex}/${data.totalFiles}`;\n          } else {\n            if (islandFileName) islandFileName.textContent = data.fileName;\n            if (islandFromNode) islandFromNode.textContent = `[ ${data.fromSlot || 'Node'} ]`;\n          }\n          if (islandSpeed) islandSpeed.textContent = 'Streaming...';\n          if (islandProgressBar) islandProgressBar.style.width = '0%';\n          if (islandPercent) islandPercent.textContent = '0%';\n          setIslandState('state-receiving');\n        } else if (data.type === 'host_transfer_progress') {\n          if (!currentHostTransfer || currentHostTransfer.fileId !== data.fileId) {\n            currentHostTransfer = {\n              fileId: data.fileId,\n              fileSize: data.totalBytes || 0,\n              totalChunks: data.totalChunks || 1,\n              startTime: Date.now(),\n              lastBytes: 0,\n              lastTime: Date.now()\n            };\n          }\n          const totalBytes = data.totalBytes || currentHostTransfer.fileSize || 0;\n          const hasByteProgress = (typeof data.receivedBytes === 'number' && totalBytes > 0);\n          const percent = hasByteProgress\n            ? Math.min(100, Math.round((data.receivedBytes / totalBytes) * 100))\n            : Math.min(100, Math.round((data.receivedTotal / (data.totalChunks || 1)) * 100));\n          if (islandProgressBar) islandProgressBar.style.width = `${percent}%`;\n          if (islandPercent) islandPercent.textContent = `${percent}%`;\n          const currentBytes = hasByteProgress\n            ? data.receivedBytes\n            : (currentHostTransfer.fileSize ? (data.receivedTotal / currentHostTransfer.totalChunks) * currentHostTransfer.fileSize : 0);\n          if (currentBytes > 0) {\n            const now = Date.now();\n            const elapsed = (now - currentHostTransfer.lastTime) / 1000;\n            if (elapsed >= 0.4) {\n              const delta = currentBytes - currentHostTransfer.lastBytes;\n              const speedMb = (delta / (1024 * 1024 * elapsed)).toFixed(1);\n              if (islandSpeed && Number(speedMb) > 0) islandSpeed.textContent = `${speedMb} MB/s`;\n              currentHostTransfer.lastBytes = currentBytes;\n              currentHostTransfer.lastTime = now;\n            }\n          }\n        } else if (data.type === 'host_transfer_cancel') {\n          if (!currentHostTransfer || currentHostTransfer.fileId === data.fileId) {\n            currentHostTransfer = null;\n            if (islandRevertTimer) clearTimeout(islandRevertTimer);\n            setIslandState('state-idle');\n          }\n        } else if (data.type === 'host_transfer_complete') {\n          lastReceivedFile = {\n            fileName: data.fileName,\n            filePath: data.filePath,\n            fileSize: data.fileSize\n          };\n          if (islandCompleteName) islandCompleteName.textContent = data.fileName;\n          if (islandCompleteSize) islandCompleteSize.textContent = formatBytes(data.fileSize);\n          setIslandState('state-complete');\n          playSuccessChime();\n          if (islandRevertTimer) clearTimeout(islandRevertTimer);\n          islandRevertTimer = setTimeout(() => {\n            setIslandState('state-idle');\n          }, 8000);\n        }\n      } catch (err) {}\n    };\n\n    if (islandOpenFolderBtn) {\n      islandOpenFolderBtn.addEventListener('click', async (e) => {\n        e.stopPropagation();\n        try {\n          const origHtml = islandOpenFolderBtn.innerHTML;\n          islandOpenFolderBtn.innerHTML = `\n            <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><polyline points=\"20 6 9 17 4 12\"></polyline></svg>\n            <span>Opened!</span>\n          `;\n          await fetch('/api/open-file', {\n            method: 'POST',\n            headers: { 'Content-Type': 'application/json' },\n            body: JSON.stringify({\n              filePath: lastReceivedFile?.filePath,\n              fileName: lastReceivedFile?.fileName\n            })\n          });\n          setTimeout(() => {\n            islandOpenFolderBtn.innerHTML = origHtml;\n          }, 2000);\n        } catch (err) {}\n      });\n    }\n\n    if (islandDismissBtn) {\n      islandDismissBtn.addEventListener('click', (e) => {\n        e.stopPropagation();\n        if (islandRevertTimer) clearTimeout(islandRevertTimer);\n        setIslandState('state-idle');\n      });\n    }\n\n    if (dynamicIsland) {\n      dynamicIsland.addEventListener('click', () => {\n        if (dynamicIsland.classList.contains('state-idle')) {\n          fetch('/api/open-folder', { method: 'POST' }).catch(() => {});\n        }\n      });\n    }\n  </script>\n</body>\n</html>\n",
  "manifest.json": "{\n  \"name\": \"uDrop - UXIOM Mesh\",\n  \"short_name\": \"uDrop\",\n  \"start_url\": \"/\",\n  \"display\": \"standalone\",\n  \"background_color\": \"#09090b\",\n  \"theme_color\": \"#09090b\",\n  \"description\": \"Zero-router, cross-platform P2P file transfer and 4K streaming\",\n  \"icons\": [\n    {\n      \"src\": \"assets/icon-brand.svg\",\n      \"sizes\": \"any\",\n      \"type\": \"image/svg+xml\",\n      \"purpose\": \"any maskable\"\n    }\n  ]\n}\n",
  "assets/icon-brand.svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 100 100\" width=\"100%\" height=\"100%\">\n  <!-- Monochromatic Zinc Squircle -->\n  <rect width=\"100\" height=\"100\" rx=\"26\" fill=\"#FAFAFA\"/>\n  <!-- Viewfinder Brackets -->\n  <rect x=\"20\" y=\"27\" width=\"6\" height=\"46\" rx=\"1\" fill=\"#09090B\"/>\n  <rect x=\"74\" y=\"27\" width=\"6\" height=\"46\" rx=\"1\" fill=\"#09090B\"/>\n  <!-- Corner Dots -->\n  <rect x=\"29\" y=\"21\" width=\"6.5\" height=\"6.5\" fill=\"#09090B\"/>\n  <rect x=\"64.5\" y=\"21\" width=\"6.5\" height=\"6.5\" fill=\"#09090B\"/>\n  <rect x=\"29\" y=\"72.5\" width=\"6.5\" height=\"6.5\" fill=\"#09090B\"/>\n  <rect x=\"64.5\" y=\"72.5\" width=\"6.5\" height=\"6.5\" fill=\"#09090B\"/>\n  <!-- Inner U Mark -->\n  <rect x=\"37.5\" y=\"36\" width=\"4.5\" height=\"23\" fill=\"#09090B\"/>\n  <rect x=\"58\" y=\"36\" width=\"4.5\" height=\"23\" fill=\"#09090B\"/>\n  <rect x=\"42\" y=\"55\" width=\"16\" height=\"4\" fill=\"#09090B\"/>\n</svg>\n"
};
